-- calc_rulebook_releases_name
-- Field: RulebookReleases.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_rulebook_releases_name(p_rulebook_release_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(rulebook_version, '') FROM rulebook_releases WHERE rulebook_release_id = p_rulebook_release_id), ' / PKO ', (SELECT NULLIF(pko_core_version_iri, '') FROM rulebook_releases WHERE rulebook_release_id = p_rulebook_release_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_rulebook_releases_expected_major
-- Field: RulebookReleases.ExpectedMajor
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_rulebook_releases_expected_major(p_rulebook_release_id TEXT)
RETURNS INTEGER AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_rulebook_releases_prev_major(p_rulebook_release_id) AS val) SELECT (CASE WHEN COALESCE((SELECT NULLIF(declared_scale, '') FROM rulebook_releases WHERE rulebook_release_id = p_rulebook_release_id), '') = 'Major' THEN ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v1)) AS v) __safe_numeric), 0) + COALESCE(1, 0)))::text ELSE ((SELECT val FROM __erb_dedup_v1))::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_rulebook_releases_expected_minor
-- Field: RulebookReleases.ExpectedMinor
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_rulebook_releases_expected_minor(p_rulebook_release_id TEXT)
RETURNS INTEGER AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_rulebook_releases_prev_minor(p_rulebook_release_id) AS val) SELECT (CASE WHEN COALESCE((SELECT NULLIF(declared_scale, '') FROM rulebook_releases WHERE rulebook_release_id = p_rulebook_release_id), '') = 'Major' THEN (0)::text ELSE (CASE WHEN COALESCE((SELECT NULLIF(declared_scale, '') FROM rulebook_releases WHERE rulebook_release_id = p_rulebook_release_id), '') = 'Minor' THEN ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v1)) AS v) __safe_numeric), 0) + COALESCE(1, 0)))::text ELSE ((SELECT val FROM __erb_dedup_v1))::text END)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_rulebook_releases_expected_patch
-- Field: RulebookReleases.ExpectedPatch
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_rulebook_releases_expected_patch(p_rulebook_release_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE((SELECT NULLIF(declared_scale, '') FROM rulebook_releases WHERE rulebook_release_id = p_rulebook_release_id), '') = 'Patch' THEN ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_rulebook_releases_prev_patch(p_rulebook_release_id)) AS v) __safe_numeric), 0) + COALESCE(1, 0)))::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_rulebook_releases_is_increment_inconsistent_with_scale
-- Field: RulebookReleases.IsIncrementInconsistentWithScale
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_rulebook_releases_is_increment_inconsistent_with_scale(p_rulebook_release_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(previous_release, '') FROM rulebook_releases WHERE rulebook_release_id = p_rulebook_release_id) IS NOT NULL, FALSE) AND COALESCE((COALESCE(COALESCE((SELECT version_major FROM rulebook_releases WHERE rulebook_release_id = p_rulebook_release_id), 0) <> COALESCE(calc_rulebook_releases_expected_major(p_rulebook_release_id), 0), FALSE) OR COALESCE(COALESCE((SELECT version_minor FROM rulebook_releases WHERE rulebook_release_id = p_rulebook_release_id), 0) <> COALESCE(calc_rulebook_releases_expected_minor(p_rulebook_release_id), 0), FALSE) OR COALESCE(COALESCE((SELECT version_patch FROM rulebook_releases WHERE rulebook_release_id = p_rulebook_release_id), 0) <> COALESCE(calc_rulebook_releases_expected_patch(p_rulebook_release_id), 0), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_rulebook_releases_days_since_previous_release
-- Field: RulebookReleases.DaysSincePreviousRelease
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_rulebook_releases_days_since_previous_release(p_rulebook_release_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN (SELECT NULLIF(previous_release, '') FROM rulebook_releases WHERE rulebook_release_id = p_rulebook_release_id) IS NULL THEN (0)::text ELSE (((((SELECT issued_at::timestamptz FROM rulebook_releases WHERE rulebook_release_id = p_rulebook_release_id))::timestamptz AT TIME ZONE 'UTC')::date - ((calc_rulebook_releases_prev_issued_at(p_rulebook_release_id))::timestamptz AT TIME ZONE 'UTC')::date))::text END)::integer;
