  SELECT ((COALESCE(COALESCE((calc_rulebook_releases_validation_run_count(p_rulebook_release_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((calc_rulebook_releases_cq_run_count(p_rulebook_release_id))::NUMERIC, 0) = 0, FALSE)));
