-- calc_organizations_is_hollowed_out_firm
-- Field: Organizations.IsHollowedOutFirm
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_organizations_is_hollowed_out_firm(p_organization_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_organizations_product_delivery_function_count(p_organization_id) AS val) SELECT ((COALESCE(COALESCE(((SELECT val FROM __erb_dedup_v1))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE(calc_organizations_provider_held_delivery_method_count(p_organization_id), 0) = COALESCE((SELECT val FROM __erb_dedup_v1), 0), FALSE)));
$$ LANGUAGE sql STABLE;

