-- calc_organizations_has_knowledge_findings_without_knowledge_sta
-- Field: Organizations.HasKnowledgeFindingsWithoutKnowledgeStaff
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_organizations_has_knowledge_findings_without_knowledge_sta(p_organization_id TEXT)
