-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_agents_is_unclassified_agent(p_agent_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(agent_kind, '') FROM agents WHERE agent_id = p_agent_id), '') <> 'Human', FALSE) AND COALESCE(COALESCE((SELECT NULLIF(agent_kind, '') FROM agents WHERE agent_id = p_agent_id), '') <> 'AIAgent', FALSE) AND COALESCE(COALESCE((SELECT NULLIF(agent_kind, '') FROM agents WHERE agent_id = p_agent_id), '') <> 'AutomatedPipeline', FALSE) AND COALESCE(COALESCE((SELECT NULLIF(agent_kind, '') FROM agents WHERE agent_id = p_agent_id), '') <> 'Organization', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

