-- calc_agents_required_mentoring_hours_per_week
-- Field: Agents.RequiredMentoringHoursPerWeek
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_agents_required_mentoring_hours_per_week(p_agent_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COALESCE(SUM((expected_weekly_hours)::numeric), 0) FROM mentorships WHERE mentor_agent = p_agent_id AND calc_mentorships_is_active(mentorship_id) = TRUE))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_agents_lacks_time_to_mentor
-- Field: Agents.LacksTimeToMentor
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_agents_lacks_time_to_mentor(p_agent_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_agents_required_mentoring_hours_per_week(p_agent_id) AS val) SELECT ((COALESCE(COALESCE(((SELECT val FROM __erb_dedup_v1))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((SELECT protected_mentoring_hours_per_week FROM agents WHERE agent_id = p_agent_id), 0) < COALESCE((SELECT val FROM __erb_dedup_v1), 0), FALSE)));
$$ LANGUAGE sql STABLE;

