CREATE OR REPLACE FUNCTION calc_procedure_versions_is_inconsistent_across_shifts(p_procedure_version_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_procedure_versions_day_deviating_run_count(p_procedure_version_id) AS val), __erb_dedup_v2 AS (SELECT calc_procedure_versions_night_deviating_run_count(p_procedure_version_id) AS val) SELECT ((COALESCE(COALESCE((calc_procedure_versions_day_run_count(p_procedure_version_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((calc_procedure_versions_night_run_count(p_procedure_version_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE((COALESCE((COALESCE(COALESCE(((SELECT val FROM __erb_dedup_v1))::NUMERIC, 0) = 0, FALSE) AND COALESCE(COALESCE(((SELECT val FROM __erb_dedup_v2))::NUMERIC, 0) > 0, FALSE)), FALSE) OR COALESCE((COALESCE(COALESCE(((SELECT val FROM __erb_dedup_v1))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE(((SELECT val FROM __erb_dedup_v2))::NUMERIC, 0) = 0, FALSE)), FALSE)), FALSE)));
$$ LANGUAGE sql STABLE;

