CREATE OR REPLACE FUNCTION calc_procedure_versions_situated_judgment_fragment_count(p_procedure_version_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM knowledge_fragments WHERE procedure_version = (SELECT NULLIF(procedure_version_id, '') FROM procedure_versions WHERE procedure_version_id = p_procedure_version_id) AND knowledge_form = 'SituatedJudgment'))::integer;
$$ LANGUAGE sql STABLE;

-- calc_procedure_versions_tacit_judgment_fragment_count
-- Field: ProcedureVersions.TacitJudgmentFragmentCount
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_procedure_versions_tacit_judgment_fragment_count(p_procedure_version_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_procedure_versions_tacit_form_fragment_count(p_procedure_version_id)) AS v) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_procedure_versions_situated_judgment_fragment_count(p_procedure_version_id)) AS v) __safe_numeric), 0)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_procedure_versions_first_step
-- Field: ProcedureVersions.FirstStep
-- Type: aggregation | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_procedure_versions_first_step(p_procedure_version_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT MAX(calc_steps_declared_first_step_key(step_id)::text) FROM steps WHERE procedure_version = p_procedure_version_id))::text;
$$ LANGUAGE sql STABLE;

-- calc_procedure_versions_fallback_step
-- Field: ProcedureVersions.FallbackStep
-- Type: aggregation | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_procedure_versions_fallback_step(p_procedure_version_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT MAX(calc_steps_declared_fallback_step_key(step_id)::text) FROM steps WHERE procedure_version = p_procedure_version_id))::text;
$$ LANGUAGE sql STABLE;

-- calc_procedure_versions_first_step_disagrees_with_graph
-- Field: ProcedureVersions.FirstStepDisagreesWithGraph
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_procedure_versions_first_step_disagrees_with_graph(p_procedure_version_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((calc_procedure_versions_declared_first_step_count(p_procedure_version_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((calc_procedure_versions_graph_entry_step_count(p_procedure_version_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE(calc_procedure_versions_first_step(p_procedure_version_id), '') <> COALESCE(calc_procedure_versions_entry_step_id(p_procedure_version_id), ''), FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_procedure_versions_declared_first_step_count
-- Field: ProcedureVersions.DeclaredFirstStepCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_procedure_versions_declared_first_step_count(p_procedure_version_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM steps WHERE procedure_version = (SELECT NULLIF(procedure_version_id, '') FROM procedure_versions WHERE procedure_version_id = p_procedure_version_id) AND is_declared_first_step = TRUE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_procedure_versions_graph_entry_step_count
-- Field: ProcedureVersions.GraphEntryStepCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_procedure_versions_graph_entry_step_count(p_procedure_version_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM steps WHERE procedure_version = (SELECT NULLIF(procedure_version_id, '') FROM procedure_versions WHERE procedure_version_id = p_procedure_version_id) AND calc_steps_is_entry_step(step_id) = TRUE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_procedure_version_links_name
-- Field: ProcedureVersionLinks.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_procedure_version_links_name(p_procedure_version_link_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(previous_procedure_version, '') FROM procedure_version_links WHERE procedure_version_link_id = p_procedure_version_link_id), ' -> ', (SELECT NULLIF(next_procedure_version, '') FROM procedure_version_links WHERE procedure_version_link_id = p_procedure_version_link_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_procedure_version_links_superseded_version_key
-- Field: ProcedureVersionLinks.SupersededVersionKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_procedure_version_links_superseded_version_key(p_procedure_version_link_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN COALESCE((SELECT NULLIF(relation_iri, '') FROM procedure_version_links WHERE procedure_version_link_id = p_procedure_version_link_id), '') = 'https://w3id.org/pko#nextVersion' THEN ((SELECT NULLIF(previous_procedure_version, '') FROM procedure_version_links WHERE procedure_version_link_id = p_procedure_version_link_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

