-- calc_procedure_status_changes_name
-- Field: ProcedureStatusChanges.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_procedure_status_changes_name(p_procedure_status_change_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(procedure_version, '') FROM procedure_status_changes WHERE procedure_status_change_id = p_procedure_status_change_id), ': ', (SELECT NULLIF(from_status, '') FROM procedure_status_changes WHERE procedure_status_change_id = p_procedure_status_change_id), ' -> ', (SELECT NULLIF(to_status, '') FROM procedure_status_changes WHERE procedure_status_change_id = p_procedure_status_change_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_procedure_status_changes_is_unattributed_change
-- Field: ProcedureStatusChanges.IsUnattributedChange
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_procedure_status_changes_is_unattributed_change(p_procedure_status_change_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((SELECT NULLIF(changed_by_agent, '') FROM procedure_status_changes WHERE procedure_status_change_id = p_procedure_status_change_id) IS NULL)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_procedure_status_changes_change_kind_contradicts_target
-- Field: ProcedureStatusChanges.ChangeKindContradictsTarget
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_procedure_status_changes_change_kind_contradicts_target(p_procedure_status_change_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((COALESCE(COALESCE((SELECT NULLIF(change_kind, '') FROM procedure_status_changes WHERE procedure_status_change_id = p_procedure_status_change_id), '') = 'Approve', FALSE) AND COALESCE(COALESCE((SELECT NULLIF(to_status, '') FROM procedure_status_changes WHERE procedure_status_change_id = p_procedure_status_change_id), '') <> 'Approved', FALSE)), FALSE) OR COALESCE((COALESCE(COALESCE((SELECT NULLIF(change_kind, '') FROM procedure_status_changes WHERE procedure_status_change_id = p_procedure_status_change_id), '') = 'Validate', FALSE) AND COALESCE(COALESCE((SELECT NULLIF(to_status, '') FROM procedure_status_changes WHERE procedure_status_change_id = p_procedure_status_change_id), '') <> 'Validation', FALSE)), FALSE) OR COALESCE((COALESCE(COALESCE((SELECT NULLIF(change_kind, '') FROM procedure_status_changes WHERE procedure_status_change_id = p_procedure_status_change_id), '') = 'Archive', FALSE) AND COALESCE(COALESCE((SELECT NULLIF(to_status, '') FROM procedure_status_changes WHERE procedure_status_change_id = p_procedure_status_change_id), '') <> 'Archived', FALSE) AND COALESCE(COALESCE((SELECT NULLIF(to_status, '') FROM procedure_status_changes WHERE procedure_status_change_id = p_procedure_status_change_id), '') <> 'Deprecated', FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

