$$ LANGUAGE sql STABLE;

-- calc_steps_output_variable_count
-- Field: Steps.OutputVariableCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_steps_output_variable_count(p_step_id TEXT)
RETURNS INTEGER AS $$
