-- calc_elicitation_sessions_name
-- Field: ElicitationSessions.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_elicitation_sessions_name(p_elicitation_session_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(method, '') FROM elicitation_sessions WHERE elicitation_session_id = p_elicitation_session_id), ' / ', erb_datetime_text(((SELECT started_at::timestamptz FROM elicitation_sessions WHERE elicitation_session_id = p_elicitation_session_id))::timestamptz)))::text;
$$ LANGUAGE sql STABLE;

-- calc_elicitation_sessions_days_since_elicited
-- Field: ElicitationSessions.DaysSinceElicited
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_elicitation_sessions_days_since_elicited(p_elicitation_session_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((((calc_elicitation_sessions_as_of_instant(p_elicitation_session_id))::timestamptz AT TIME ZONE 'UTC')::date - (((SELECT ended_at::timestamptz FROM elicitation_sessions WHERE elicitation_session_id = p_elicitation_session_id))::timestamptz AT TIME ZONE 'UTC')::date))::integer;
$$ LANGUAGE sql STABLE;

-- calc_elicitation_sessions_is_single_witness_method
-- Field: ElicitationSessions.IsSingleWitnessMethod
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_elicitation_sessions_is_single_witness_method(p_elicitation_session_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(method, '') FROM elicitation_sessions WHERE elicitation_session_id = p_elicitation_session_id), '') = 'Shadowing', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(method, '') FROM elicitation_sessions WHERE elicitation_session_id = p_elicitation_session_id), '') = 'PractitionerInterview', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_elicitation_sessions_valid_fragments_produced
-- Field: ElicitationSessions.ValidFragmentsProduced
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_elicitation_sessions_valid_fragments_produced(p_elicitation_session_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM knowledge_fragments WHERE calc_knowledge_fragments_valid_fragment_session_key(knowledge_fragment_id) = (SELECT NULLIF(elicitation_session_id, '') FROM elicitation_sessions WHERE elicitation_session_id = p_elicitation_session_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_elicitation_sessions_is_high_yield_session
-- Field: ElicitationSessions.IsHighYieldSession
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_elicitation_sessions_is_high_yield_session(p_elicitation_session_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((calc_elicitation_sessions_valid_fragments_produced(p_elicitation_session_id))::NUMERIC, 0) >= 3)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_elicitation_sessions_is_concentrated_single_witness
-- Field: ElicitationSessions.IsConcentratedSingleWitness
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_elicitation_sessions_is_concentrated_single_witness(p_elicitation_session_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_elicitation_sessions_is_single_witness_method(p_elicitation_session_id), FALSE) AND COALESCE(calc_elicitation_sessions_is_high_yield_session(p_elicitation_session_id), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_elicitation_sessions_is_stale_concentrated_witness
-- Field: ElicitationSessions.IsStaleConcentratedWitness
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_elicitation_sessions_is_stale_concentrated_witness(p_elicitation_session_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_elicitation_sessions_is_concentrated_single_witness(p_elicitation_session_id), FALSE) AND COALESCE(COALESCE((calc_elicitation_sessions_days_since_elicited(p_elicitation_session_id))::NUMERIC, 0) > 180, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_elicitation_sessions_concentrated_session_version_key
-- Field: ElicitationSessions.ConcentratedSessionVersionKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_elicitation_sessions_concentrated_session_version_key(p_elicitation_session_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_elicitation_sessions_is_concentrated_single_witness(p_elicitation_session_id) THEN ((SELECT NULLIF(procedure_version, '') FROM elicitation_sessions WHERE elicitation_session_id = p_elicitation_session_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_elicitation_sessions_elicitation_mode
-- Field: ElicitationSessions.ElicitationMode
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_elicitation_sessions_elicitation_mode(p_elicitation_session_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN COALESCE((SELECT NULLIF(method, '') FROM elicitation_sessions WHERE elicitation_session_id = p_elicitation_session_id), '') = 'PractitionerInterview' THEN ('Interview')::text ELSE (CASE WHEN COALESCE((SELECT NULLIF(method, '') FROM elicitation_sessions WHERE elicitation_session_id = p_elicitation_session_id), '') = 'Shadowing' THEN ('Observation')::text ELSE (CASE WHEN COALESCE((SELECT NULLIF(method, '') FROM elicitation_sessions WHERE elicitation_session_id = p_elicitation_session_id), '') = 'FacilitatedWorkshop' THEN ('Workshop')::text ELSE (CASE WHEN COALESCE((SELECT NULLIF(method, '') FROM elicitation_sessions WHERE elicitation_session_id = p_elicitation_session_id), '') = 'CriticalIncidentTechnique' THEN ('Incident')::text ELSE (CASE WHEN (COALESCE(COALESCE((SELECT NULLIF(method, '') FROM elicitation_sessions WHERE elicitation_session_id = p_elicitation_session_id), '') = 'ThinkAloudProtocol', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(method, '') FROM elicitation_sessions WHERE elicitation_session_id = p_elicitation_session_id), '') = 'RetrospectiveProtocol', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(method, '') FROM elicitation_sessions WHERE elicitation_session_id = p_elicitation_session_id), '') = 'ConceptLaddering', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(method, '') FROM elicitation_sessions WHERE elicitation_session_id = p_elicitation_session_id), '') = 'RepertoryGrid', FALSE)) THEN ('Protocol')::text ELSE ('Other')::text END)::text END)::text END)::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_elicitation_sessions_is_interview
-- Field: ElicitationSessions.IsInterview
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_elicitation_sessions_is_interview(p_elicitation_session_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE(calc_elicitation_sessions_elicitation_mode(p_elicitation_session_id), '') = 'Interview')::boolean;
$$ LANGUAGE sql STABLE;

-- calc_elicitation_sessions_is_workshop
-- Field: ElicitationSessions.IsWorkshop
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_elicitation_sessions_is_workshop(p_elicitation_session_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE(calc_elicitation_sessions_elicitation_mode(p_elicitation_session_id), '') = 'Workshop')::boolean;
$$ LANGUAGE sql STABLE;

-- calc_elicitation_sessions_why_probe_count
-- Field: ElicitationSessions.WhyProbeCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_elicitation_sessions_why_probe_count(p_elicitation_session_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM interview_probes WHERE elicitation_session = (SELECT NULLIF(elicitation_session_id, '') FROM elicitation_sessions WHERE elicitation_session_id = p_elicitation_session_id) AND probe_kind = 'Why'))::integer;
$$ LANGUAGE sql STABLE;

-- calc_elicitation_sessions_shortfall_probe_count
-- Field: ElicitationSessions.ShortfallProbeCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_elicitation_sessions_shortfall_probe_count(p_elicitation_session_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM interview_probes WHERE elicitation_session = (SELECT NULLIF(elicitation_session_id, '') FROM elicitation_sessions WHERE elicitation_session_id = p_elicitation_session_id) AND probe_kind = 'ProcedureFallsShort'))::integer;
$$ LANGUAGE sql STABLE;

-- calc_elicitation_sessions_is_interview_without_why_probe
-- Field: ElicitationSessions.IsInterviewWithoutWhyProbe
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_elicitation_sessions_is_interview_without_why_probe(p_elicitation_session_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_elicitation_sessions_is_interview(p_elicitation_session_id), FALSE) AND COALESCE(COALESCE((calc_elicitation_sessions_why_probe_count(p_elicitation_session_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_elicitation_sessions_is_interview_without_shortfall_probe
-- Field: ElicitationSessions.IsInterviewWithoutShortfallProbe
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_elicitation_sessions_is_interview_without_shortfall_probe(p_elicitation_session_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_elicitation_sessions_is_interview(p_elicitation_session_id), FALSE) AND COALESCE(COALESCE((calc_elicitation_sessions_shortfall_probe_count(p_elicitation_session_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_elicitation_sessions_initiator_count
-- Field: ElicitationSessions.InitiatorCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_elicitation_sessions_initiator_count(p_elicitation_session_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM elicitation_participants WHERE elicitation_session = (SELECT NULLIF(elicitation_session_id, '') FROM elicitation_sessions WHERE elicitation_session_id = p_elicitation_session_id) AND process_stake = 'Initiates'))::integer;
$$ LANGUAGE sql STABLE;

-- calc_elicitation_sessions_executor_count
-- Field: ElicitationSessions.ExecutorCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_elicitation_sessions_executor_count(p_elicitation_session_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM elicitation_participants WHERE elicitation_session = (SELECT NULLIF(elicitation_session_id, '') FROM elicitation_sessions WHERE elicitation_session_id = p_elicitation_session_id) AND process_stake = 'Executes'))::integer;
$$ LANGUAGE sql STABLE;

-- calc_elicitation_sessions_dependent_count
-- Field: ElicitationSessions.DependentCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_elicitation_sessions_dependent_count(p_elicitation_session_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM elicitation_participants WHERE elicitation_session = (SELECT NULLIF(elicitation_session_id, '') FROM elicitation_sessions WHERE elicitation_session_id = p_elicitation_session_id) AND process_stake = 'DependsOnResults'))::integer;
$$ LANGUAGE sql STABLE;

-- calc_elicitation_sessions_uninvited_participant_count
-- Field: ElicitationSessions.UninvitedParticipantCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_elicitation_sessions_uninvited_participant_count(p_elicitation_session_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM elicitation_participants WHERE elicitation_session = (SELECT NULLIF(elicitation_session_id, '') FROM elicitation_sessions WHERE elicitation_session_id = p_elicitation_session_id) AND is_usually_invited = FALSE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_elicitation_sessions_gathers_whole_process_chain
-- Field: ElicitationSessions.GathersWholeProcessChain
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_elicitation_sessions_gathers_whole_process_chain(p_elicitation_session_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_elicitation_sessions_is_workshop(p_elicitation_session_id), FALSE) AND COALESCE(COALESCE((calc_elicitation_sessions_initiator_count(p_elicitation_session_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((calc_elicitation_sessions_executor_count(p_elicitation_session_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((calc_elicitation_sessions_dependent_count(p_elicitation_session_id))::NUMERIC, 0) > 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_elicitation_sessions_is_workshop_without_usual_outsiders
-- Field: ElicitationSessions.IsWorkshopWithoutUsualOutsiders
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_elicitation_sessions_is_workshop_without_usual_outsiders(p_elicitation_session_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_elicitation_sessions_is_workshop(p_elicitation_session_id), FALSE) AND COALESCE(COALESCE((calc_elicitation_sessions_uninvited_participant_count(p_elicitation_session_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_elicitation_sessions_facilitator_knowledge_engineer_role_c
