CREATE OR REPLACE FUNCTION calc_elicitation_sessions_facilitator_is_knowledge_engineer(p_elicitation_session_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((calc_elicitation_sessions_facilitator_knowledge_engineer_role_c(p_elicitation_session_id))::NUMERIC, 0) > 0)::boolean;
