CREATE OR REPLACE FUNCTION calc_elicitation_sessions_is_ke_field_session(p_elicitation_session_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_elicitation_sessions_facilitator_is_knowledge_engineer(p_elicitation_session_id), FALSE) AND COALESCE(COALESCE((SELECT NULLIF(setting, '') FROM elicitation_sessions WHERE elicitation_session_id = p_elicitation_session_id), '') = 'InSitu', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

