  SELECT ((COALESCE(calc_knowledge_fragments_is_single_point_of_failure(p_knowledge_fragment_id), FALSE) AND COALESCE(calc_knowledge_fragments_is_overdue_for_review(p_knowledge_fragment_id), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

