$$ LANGUAGE sql STABLE;

-- calc_knowledge_fragments_is_orphaned_by_role
-- Field: KnowledgeFragments.IsOrphanedByRole
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_fragments_is_orphaned_by_role(p_knowledge_fragment_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_knowledge_fragments_is_currently_valid(p_knowledge_fragment_id), FALSE) AND COALESCE(calc_knowledge_fragments_owner_role_is_vacated(p_knowledge_fragment_id), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_fragments_valid_fragment_version_key
-- Field: KnowledgeFragments.ValidFragmentVersionKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_knowledge_fragments_valid_fragment_version_key(p_knowledge_fragment_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_knowledge_fragments_is_currently_valid(p_knowledge_fragment_id) THEN ((SELECT NULLIF(procedure_version, '') FROM knowledge_fragments WHERE knowledge_fragment_id = p_knowledge_fragment_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_fragments_is_flattened_to_brittle_rule
-- Field: KnowledgeFragments.IsFlattenedToBrittleRule
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_fragments_is_flattened_to_brittle_rule(p_knowledge_fragment_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((COALESCE(COALESCE((SELECT NULLIF(knowledge_form, '') FROM knowledge_fragments WHERE knowledge_fragment_id = p_knowledge_fragment_id), '') = 'Tacit', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(knowledge_form, '') FROM knowledge_fragments WHERE knowledge_fragment_id = p_knowledge_fragment_id), '') = 'SituatedJudgment', FALSE)), FALSE) AND COALESCE(COALESCE((SELECT NULLIF(encoded_as, '') FROM knowledge_fragments WHERE knowledge_fragment_id = p_knowledge_fragment_id), '') = 'HardRule', FALSE) AND COALESCE((SELECT NULLIF(stated_conditions, '') FROM knowledge_fragments WHERE knowledge_fragment_id = p_knowledge_fragment_id) IS NULL, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

