CREATE OR REPLACE FUNCTION calc_knowledge_fragments_corroboration_count(p_knowledge_fragment_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM fragment_corroborations WHERE knowledge_fragment = (SELECT NULLIF(knowledge_fragment_id, '') FROM knowledge_fragments WHERE knowledge_fragment_id = p_knowledge_fragment_id) AND agrees = TRUE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_fragments_rests_on_single_data_point
-- Field: KnowledgeFragments.RestsOnSingleDataPoint
