-- calc_knowledge_gaps_name
-- Field: KnowledgeGaps.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_name(p_knowledge_gap_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(severity, '') FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id), ': ', LEFT(((SELECT NULLIF(statement, '') FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id))::text, (60)::integer)))::text;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_is_open
-- Field: KnowledgeGaps.IsOpen
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_is_open(p_knowledge_gap_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(status, '') FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id), '') = 'Open', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(status, '') FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id), '') = 'Investigating', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_open_gap_version_key
-- Field: KnowledgeGaps.OpenGapVersionKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_open_gap_version_key(p_knowledge_gap_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN (COALESCE(calc_knowledge_gaps_is_open(p_knowledge_gap_id), FALSE) AND COALESCE(COALESCE((SELECT NULLIF(severity, '') FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id), '') = 'High', FALSE)) THEN ((SELECT NULLIF(procedure_version, '') FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_is_blocking
-- Field: KnowledgeGaps.IsBlocking
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_is_blocking(p_knowledge_gap_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((SELECT NULLIF(blocking_kind, '') FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id), '') = 'Blocking')::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_is_open_and_blocking
-- Field: KnowledgeGaps.IsOpenAndBlocking
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_is_open_and_blocking(p_knowledge_gap_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_knowledge_gaps_is_open(p_knowledge_gap_id), FALSE) AND COALESCE(calc_knowledge_gaps_is_blocking(p_knowledge_gap_id), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_days_open
-- Field: KnowledgeGaps.DaysOpen
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_days_open(p_knowledge_gap_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN calc_knowledge_gaps_is_open(p_knowledge_gap_id) THEN ((((calc_knowledge_gaps_as_of_instant(p_knowledge_gap_id))::timestamptz AT TIME ZONE 'UTC')::date - (((SELECT identified_at::timestamptz FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id))::timestamptz AT TIME ZONE 'UTC')::date))::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_tolerance_days
-- Field: KnowledgeGaps.ToleranceDays
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_tolerance_days(p_knowledge_gap_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE((SELECT NULLIF(severity, '') FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id), '') = 'High' THEN (30)::text ELSE (CASE WHEN COALESCE((SELECT NULLIF(severity, '') FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id), '') = 'Medium' THEN (90)::text ELSE (180)::text END)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_is_overdue_gap
-- Field: KnowledgeGaps.IsOverdueGap
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_is_overdue_gap(p_knowledge_gap_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE(calc_knowledge_gaps_days_open(p_knowledge_gap_id), 0) > COALESCE(calc_knowledge_gaps_tolerance_days(p_knowledge_gap_id), 0))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_has_resolution_plan
-- Field: KnowledgeGaps.HasResolutionPlan
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_has_resolution_plan(p_knowledge_gap_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((SELECT NULLIF(resolution_plan, '') FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id) IS NOT NULL)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_is_abandoned_unknown
-- Field: KnowledgeGaps.IsAbandonedUnknown
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_is_abandoned_unknown(p_knowledge_gap_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_knowledge_gaps_is_overdue_gap(p_knowledge_gap_id), FALSE) AND COALESCE((COALESCE(NOT (COALESCE(calc_knowledge_gaps_has_resolution_plan(p_knowledge_gap_id), FALSE)), FALSE) OR COALESCE(NOT (COALESCE(calc_knowledge_gaps_owner_is_still_engaged(p_knowledge_gap_id), FALSE)), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_open_blocking_gap_version_key
-- Field: KnowledgeGaps.OpenBlockingGapVersionKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_open_blocking_gap_version_key(p_knowledge_gap_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_knowledge_gaps_is_open_and_blocking(p_knowledge_gap_id) THEN ((SELECT NULLIF(procedure_version, '') FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_is_ownerless_open_gap
-- Field: KnowledgeGaps.IsOwnerlessOpenGap
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_is_ownerless_open_gap(p_knowledge_gap_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_knowledge_gaps_is_open(p_knowledge_gap_id), FALSE) AND COALESCE(calc_knowledge_gaps_owner_role_is_vacated(p_knowledge_gap_id), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_is_known_and_unresolved
-- Field: KnowledgeGaps.IsKnownAndUnresolved
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_is_known_and_unresolved(p_knowledge_gap_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT identified_at::timestamptz FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id) IS NOT NULL, FALSE) AND COALESCE(calc_knowledge_gaps_is_open(p_knowledge_gap_id), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_is_gatekeeping_or_sabotage
-- Field: KnowledgeGaps.IsGatekeepingOrSabotage
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_is_gatekeeping_or_sabotage(p_knowledge_gap_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(gap_cause, '') FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id), '') = 'Gatekeeping', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(gap_cause, '') FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id), '') = 'Sabotage', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_is_unattributed_gatekeeping
-- Field: KnowledgeGaps.IsUnattributedGatekeeping
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_is_unattributed_gatekeeping(p_knowledge_gap_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT holder_declined_to_share FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id), FALSE), FALSE) AND COALESCE(NOT (COALESCE(calc_knowledge_gaps_is_gatekeeping_or_sabotage(p_knowledge_gap_id), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_is_required_gatekept_uncodified
-- Field: KnowledgeGaps.IsRequiredGatekeptUncodified
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_is_required_gatekept_uncodified(p_knowledge_gap_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_knowledge_gaps_is_gatekeeping_or_sabotage(p_knowledge_gap_id), FALSE) AND COALESCE(COALESCE((SELECT NULLIF(blocking_kind, '') FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id), '') = 'Blocking', FALSE) AND COALESCE((SELECT NULLIF(codified_as_fragment, '') FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id) IS NULL, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

