  SELECT ((COALESCE(calc_step_executions_step_is_approval(p_step_execution_id), FALSE) AND COALESCE(COALESCE((calc_step_executions_prepared_by_this_agent_count(p_step_execution_id))::NUMERIC, 0) > 0, FALSE)));
$$ LANGUAGE sql STABLE;

