CREATE OR REPLACE FUNCTION calc_requirement_satisfactions_is_asserted_only(p_requirement_satisfaction_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_requirement_satisfactions_requirement_is_blocking(p_requirement_satisfaction_id), FALSE) AND COALESCE(calc_requirement_satisfactions_is_fully_satisfied(p_requirement_satisfaction_id), FALSE) AND COALESCE(NOT (COALESCE(calc_requirement_satisfactions_requirement_has_computed_witness(p_requirement_satisfaction_id), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_requirement_satisfactions_asserted_only_execution_key
-- Field: RequirementSatisfactions.AssertedOnlyExecutionKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_requirement_satisfactions_asserted_only_execution_key(p_requirement_satisfaction_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_requirement_satisfactions_is_asserted_only(p_requirement_satisfaction_id) THEN (calc_requirement_satisfactions_parent_procedure_execution(p_requirement_satisfaction_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_requirement_satisfactions_step_execution_when_scored
-- Field: RequirementSatisfactions.StepExecutionWhenScored
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_requirement_satisfactions_step_execution_when_scored(p_requirement_satisfaction_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN (SELECT NULLIF(satisfaction_level, '') FROM requirement_satisfactions WHERE requirement_satisfaction_id = p_requirement_satisfaction_id) IS NOT NULL THEN ((SELECT NULLIF(step_execution, '') FROM requirement_satisfactions WHERE requirement_satisfaction_id = p_requirement_satisfaction_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_requirement_satisfactions_is_human_evaluated
-- Field: RequirementSatisfactions.IsHumanEvaluated
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_requirement_satisfactions_is_human_evaluated(p_requirement_satisfaction_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE(calc_requirement_satisfactions_evaluator_agent_kind(p_requirement_satisfaction_id), '') = 'Human')::boolean;
$$ LANGUAGE sql STABLE;

-- calc_requirement_satisfactions_is_invalid_approval
-- Field: RequirementSatisfactions.IsInvalidApproval
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_requirement_satisfactions_is_invalid_approval(p_requirement_satisfaction_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE(calc_requirement_satisfactions_requirement_is_approval_type(p_requirement_satisfaction_id), '') = 'Approval', FALSE) AND COALESCE((COALESCE(NOT (COALESCE(calc_requirement_satisfactions_is_fully_satisfied(p_requirement_satisfaction_id), FALSE)), FALSE) OR COALESCE(NOT (COALESCE(calc_requirement_satisfactions_is_human_evaluated(p_requirement_satisfaction_id), FALSE)), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_requirement_satisfactions_run_when_invalid_approval
-- Field: RequirementSatisfactions.RunWhenInvalidApproval
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_requirement_satisfactions_run_when_invalid_approval(p_requirement_satisfaction_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_requirement_satisfactions_is_invalid_approval(p_requirement_satisfaction_id) THEN (calc_requirement_satisfactions_procedure_execution_of_satisfact(p_requirement_satisfaction_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_requirement_satisfactions_is_clearance_by_unfalsified_cont
-- Field: RequirementSatisfactions.IsClearanceByUnfalsifiedControl
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_requirement_satisfactions_is_clearance_by_unfalsified_cont(p_requirement_satisfaction_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_requirement_satisfactions_is_fully_satisfied(p_requirement_satisfaction_id), FALSE) AND COALESCE(calc_requirement_satisfactions_requirement_is_blocking(p_requirement_satisfaction_id), FALSE) AND COALESCE(calc_requirement_satisfactions_requirement_is_unfalsified(p_requirement_satisfaction_id), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_requirement_satisfactions_unfalsified_clearance_step_key
-- Field: RequirementSatisfactions.UnfalsifiedClearanceStepKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_requirement_satisfactions_unfalsified_clearance_step_key(p_requirement_satisfaction_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN (calc_requirement_satisfactions_is_clearance_by_unfalsified_cont(p_requirement_satisfaction_id) = 'true') THEN ((SELECT NULLIF(step_execution, '') FROM requirement_satisfactions WHERE requirement_satisfaction_id = p_requirement_satisfaction_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_requirement_satisfactions_evaluator_is_step_executor
-- Field: RequirementSatisfactions.EvaluatorIsStepExecutor
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_requirement_satisfactions_evaluator_is_step_executor(p_requirement_satisfaction_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((SELECT NULLIF(evaluated_by_agent, '') FROM requirement_satisfactions WHERE requirement_satisfaction_id = p_requirement_satisfaction_id), '') = COALESCE(calc_requirement_satisfactions_scored_step_executor_agent(p_requirement_satisfaction_id), ''))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_requirement_satisfactions_evaluator_owns_the_run
-- Field: RequirementSatisfactions.EvaluatorOwnsTheRun
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_requirement_satisfactions_evaluator_owns_the_run(p_requirement_satisfaction_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((SELECT NULLIF(evaluated_by_agent, '') FROM requirement_satisfactions WHERE requirement_satisfaction_id = p_requirement_satisfaction_id), '') = COALESCE(calc_requirement_satisfactions_run_owner_agent(p_requirement_satisfaction_id), ''))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_requirement_satisfactions_is_interested_party_assertion
-- Field: RequirementSatisfactions.IsInterestedPartyAssertion
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_requirement_satisfactions_is_interested_party_assertion(p_requirement_satisfaction_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_requirement_satisfactions_is_asserted_only(p_requirement_satisfaction_id), FALSE) AND COALESCE((COALESCE(calc_requirement_satisfactions_evaluator_is_step_executor(p_requirement_satisfaction_id), FALSE) OR COALESCE(calc_requirement_satisfactions_evaluator_owns_the_run(p_requirement_satisfaction_id), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_requirement_satisfactions_has_written_evidence
-- Field: RequirementSatisfactions.HasWrittenEvidence
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_requirement_satisfactions_has_written_evidence(p_requirement_satisfaction_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((SELECT NULLIF(evidence, '') FROM requirement_satisfactions WHERE requirement_satisfaction_id = p_requirement_satisfaction_id) IS NOT NULL)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_requirement_satisfactions_is_bare_assertion
-- Field: RequirementSatisfactions.IsBareAssertion
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_requirement_satisfactions_is_bare_assertion(p_requirement_satisfaction_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_requirement_satisfactions_is_asserted_only(p_requirement_satisfaction_id), FALSE) AND COALESCE(NOT (COALESCE(calc_requirement_satisfactions_has_written_evidence(p_requirement_satisfaction_id), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_requirement_satisfactions_interested_assertion_execution_k
-- Field: RequirementSatisfactions.InterestedAssertionExecutionKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_requirement_satisfactions_interested_assertion_execution_k(p_requirement_satisfaction_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_requirement_satisfactions_is_interested_party_assertion(p_requirement_satisfaction_id) THEN (calc_requirement_satisfactions_parent_procedure_execution(p_requirement_satisfaction_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_requirement_satisfactions_is_computedly_witnessed
-- Field: RequirementSatisfactions.IsComputedlyWitnessed
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_requirement_satisfactions_is_computedly_witnessed(p_requirement_satisfaction_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_requirement_satisfactions_requirement_is_blocking(p_requirement_satisfaction_id), FALSE) AND COALESCE(calc_requirement_satisfactions_requirement_has_computed_witness(p_requirement_satisfaction_id), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_requirement_satisfactions_computed_witness_execution_key
-- Field: RequirementSatisfactions.ComputedWitnessExecutionKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_requirement_satisfactions_computed_witness_execution_key(p_requirement_satisfaction_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_requirement_satisfactions_is_computedly_witnessed(p_requirement_satisfaction_id) THEN (calc_requirement_satisfactions_parent_procedure_execution(p_requirement_satisfaction_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_requirement_satisfactions_was_scored_after_attestation
-- Field: RequirementSatisfactions.WasScoredAfterAttestation
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_requirement_satisfactions_was_scored_after_attestation(p_requirement_satisfaction_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE(((EXTRACT(EPOCH FROM (((SELECT evaluated_at::timestamptz FROM requirement_satisfactions WHERE requirement_satisfaction_id = p_requirement_satisfaction_id))::timestamptz - (calc_requirement_satisfactions_attestation_instant_for_run(p_requirement_satisfaction_id))::timestamptz)) / 60))::NUMERIC, 0) > 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_requirement_satisfactions_post_attestation_score_execution
-- Field: RequirementSatisfactions.PostAttestationScoreExecutionKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_requirement_satisfactions_post_attestation_score_execution(p_requirement_satisfaction_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_requirement_satisfactions_was_scored_after_attestation(p_requirement_satisfaction_id) THEN (calc_requirement_satisfactions_parent_procedure_execution(p_requirement_satisfaction_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_errors_name
-- Field: Errors.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_errors_name(p_error_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(error_code, '') FROM errors WHERE error_id = p_error_id), ' - ', (SELECT NULLIF(label, '') FROM errors WHERE error_id = p_error_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_errors_remedy_step_count
-- Field: Errors.RemedyStepCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_errors_remedy_step_count(p_error_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM steps WHERE remedy_for_error = (SELECT NULLIF(error_id, '') FROM errors WHERE error_id = p_error_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_errors_occurrence_count
-- Field: Errors.OccurrenceCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_errors_occurrence_count(p_error_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM issue_occurrences WHERE error = (SELECT NULLIF(error_id, '') FROM errors WHERE error_id = p_error_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_errors_has_no_remedy_step
-- Field: Errors.HasNoRemedyStep
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_errors_has_no_remedy_step(p_error_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((calc_errors_occurrence_count(p_error_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((calc_errors_remedy_step_count(p_error_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_issue_occurrences_executed_step
-- Field: IssueOccurrences.ExecutedStep
-- Type: lookup | DataType: string | Returns: TEXT
-- Lookup: Step from related StepExecutions


CREATE OR REPLACE FUNCTION calc_issue_occurrences_executed_step(p_issue_occurrence_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT step::text FROM step_executions WHERE step_execution_id = (SELECT step_execution FROM issue_occurrences WHERE issue_occurrence_id = p_issue_occurrence_id));
$$ LANGUAGE sql STABLE;

-- calc_issue_occurrences_redesign_implemented_at
-- Field: IssueOccurrences.RedesignImplementedAt
-- Type: lookup | DataType: datetime | Returns: TIMESTAMPTZ
-- Lookup: ImplementedAt from related ChangeRequests


CREATE OR REPLACE FUNCTION calc_issue_occurrences_redesign_implemented_at(p_issue_occurrence_id TEXT)
RETURNS TIMESTAMPTZ AS $$
  SELECT (SELECT implemented_at::timestamptz FROM change_requests WHERE change_request_id = (SELECT redesign_change_request FROM issue_occurrences WHERE issue_occurrence_id = p_issue_occurrence_id));
$$ LANGUAGE sql STABLE;

-- calc_issue_occurrences_name
-- Field: IssueOccurrences.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_issue_occurrences_name(p_issue_occurrence_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(error, '') FROM issue_occurrences WHERE issue_occurrence_id = p_issue_occurrence_id), ' @ ', erb_datetime_text(((SELECT occurred_at::timestamptz FROM issue_occurrences WHERE issue_occurrence_id = p_issue_occurrence_id))::timestamptz)))::text;
$$ LANGUAGE sql STABLE;

-- calc_issue_occurrences_is_unresolved
-- Field: IssueOccurrences.IsUnresolved
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_issue_occurrences_is_unresolved(p_issue_occurrence_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(status, '') FROM issue_occurrences WHERE issue_occurrence_id = p_issue_occurrence_id), '') = 'Open', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(status, '') FROM issue_occurrences WHERE issue_occurrence_id = p_issue_occurrence_id), '') = 'Investigating', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(status, '') FROM issue_occurrences WHERE issue_occurrence_id = p_issue_occurrence_id), '') = 'Monitoring', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_issue_occurrences_step_execution_when_unresolved
-- Field: IssueOccurrences.StepExecutionWhenUnresolved
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_issue_occurrences_step_execution_when_unresolved(p_issue_occurrence_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_issue_occurrences_is_unresolved(p_issue_occurrence_id) THEN ((SELECT NULLIF(step_execution, '') FROM issue_occurrences WHERE issue_occurrence_id = p_issue_occurrence_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_issue_occurrences_failed_condition_count_on_run
-- Field: IssueOccurrences.FailedConditionCountOnRun
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_issue_occurrences_failed_condition_count_on_run(p_issue_occurrence_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COALESCE(SUM((calc_step_executions_failed_precondition_count(step_execution_id))::numeric), 0) FROM step_executions WHERE step_execution_id = (SELECT NULLIF(step_execution, '') FROM issue_occurrences WHERE issue_occurrence_id = p_issue_occurrence_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_issue_occurrences_coincided_with_failed_condition
-- Field: IssueOccurrences.CoincidedWithFailedCondition
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_issue_occurrences_coincided_with_failed_condition(p_issue_occurrence_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((calc_issue_occurrences_failed_condition_count_on_run(p_issue_occurrence_id))::NUMERIC, 0) > 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_issue_occurrences_has_no_recorded_solution
-- Field: IssueOccurrences.HasNoRecordedSolution
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_issue_occurrences_has_no_recorded_solution(p_issue_occurrence_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((SELECT NULLIF(issue_solution, '') FROM issue_occurrences WHERE issue_occurrence_id = p_issue_occurrence_id) IS NULL)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_issue_occurrences_is_failure_without_landed_redesign
-- Field: IssueOccurrences.IsFailureWithoutLandedRedesign
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_issue_occurrences_is_failure_without_landed_redesign(p_issue_occurrence_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(redesign_change_request, '') FROM issue_occurrences WHERE issue_occurrence_id = p_issue_occurrence_id) IS NULL, FALSE) OR COALESCE(calc_issue_occurrences_redesign_implemented_at(p_issue_occurrence_id) IS NULL, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_issue_occurrences_improvement_cycle_path
-- Field: IssueOccurrences.ImprovementCyclePath
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_issue_occurrences_improvement_cycle_path(p_issue_occurrence_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN (SELECT NULLIF(redesign_change_request, '') FROM issue_occurrences WHERE issue_occurrence_id = p_issue_occurrence_id) IS NULL THEN ('')::text ELSE (CONCAT('Observed at ', calc_issue_occurrences_executed_step(p_issue_occurrence_id), ' by ', (SELECT NULLIF(encountered_by_agent, '') FROM issue_occurrences WHERE issue_occurrence_id = p_issue_occurrence_id), '; recorded as ', (SELECT NULLIF(error, '') FROM issue_occurrences WHERE issue_occurrence_id = p_issue_occurrence_id), ' (', (SELECT NULLIF(issue_cause, '') FROM issue_occurrences WHERE issue_occurrence_id = p_issue_occurrence_id), '); redesigned by ', (SELECT NULLIF(redesign_change_request, '') FROM issue_occurrences WHERE issue_occurrence_id = p_issue_occurrence_id)))::text END)::text;
$$ LANGUAGE sql STABLE;

-- get_faqs_question
-- Helper function: Get Question from FAQs by FaqId
-- Used for join-free cross-table references in aggregations

CREATE OR REPLACE FUNCTION get_faqs_question(p_faq_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT question FROM faqs WHERE faq_id = p_faq_id);
$$ LANGUAGE sql STABLE;

-- get_faqs_answer
-- Helper function: Get Answer from FAQs by FaqId
-- Used for join-free cross-table references in aggregations

CREATE OR REPLACE FUNCTION get_faqs_answer(p_faq_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT answer FROM faqs WHERE faq_id = p_faq_id);
$$ LANGUAGE sql STABLE;

-- get_faqs_semantic_type_iri
-- Helper function: Get SemanticTypeIri from FAQs by FaqId
-- Used for join-free cross-table references in aggregations

CREATE OR REPLACE FUNCTION get_faqs_semantic_type_iri(p_faq_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT semantic_type_iri FROM faqs WHERE faq_id = p_faq_id);
$$ LANGUAGE sql STABLE;

-- calc_user_questions_name
-- Field: UserQuestions.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_user_questions_name(p_user_question_id TEXT)
RETURNS TEXT AS $$
  SELECT (LEFT(((SELECT NULLIF(question_text, '') FROM user_questions WHERE user_question_id = p_user_question_id))::text, (70)::integer))::text;
$$ LANGUAGE sql STABLE;

-- calc_user_questions_is_unaddressed_question
-- Field: UserQuestions.IsUnaddressedQuestion
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_user_questions_is_unaddressed_question(p_user_question_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(addressed_by_resource, '') FROM user_questions WHERE user_question_id = p_user_question_id) IS NULL, FALSE) AND COALESCE((SELECT NULLIF(resolved_by_faq, '') FROM user_questions WHERE user_question_id = p_user_question_id) IS NULL, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_user_feedback_name
-- Field: UserFeedback.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_user_feedback_name(p_user_feedback_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(disposition, '') FROM user_feedback WHERE user_feedback_id = p_user_feedback_id), ': ', LEFT(((SELECT NULLIF(feedback_text, '') FROM user_feedback WHERE user_feedback_id = p_user_feedback_id))::text, (60)::integer)))::text;
$$ LANGUAGE sql STABLE;

-- calc_user_feedback_is_unactioned_procedure_critique
-- Field: UserFeedback.IsUnactionedProcedureCritique
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_user_feedback_is_unactioned_procedure_critique(p_user_feedback_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(feedback_on_procedure, '') FROM user_feedback WHERE user_feedback_id = p_user_feedback_id) IS NOT NULL, FALSE) AND COALESCE((SELECT NULLIF(change_request_key, '') FROM user_feedback WHERE user_feedback_id = p_user_feedback_id) IS NULL, FALSE) AND COALESCE(COALESCE((SELECT NULLIF(disposition, '') FROM user_feedback WHERE user_feedback_id = p_user_feedback_id), '') <> 'Declined', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_user_feedback_collection_follow_up_count
-- Field: UserFeedback.CollectionFollowUpCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_user_feedback_collection_follow_up_count(p_user_feedback_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM collected_source_materials WHERE prompted_by_feedback = (SELECT NULLIF(user_feedback_id, '') FROM user_feedback WHERE user_feedback_id = p_user_feedback_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_user_feedback_is_tacit_signal_not_fed_into_collection
-- Field: UserFeedback.IsTacitSignalNotFedIntoCollection
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_user_feedback_is_tacit_signal_not_fed_into_collection(p_user_feedback_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT reveals_tacit_knowledge FROM user_feedback WHERE user_feedback_id = p_user_feedback_id), FALSE), FALSE) AND COALESCE(COALESCE((calc_user_feedback_collection_follow_up_count(p_user_feedback_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_stewardship_assignments_as_of_instant
-- Field: StewardshipAssignments.AsOfInstant
-- Type: lookup | DataType: datetime | Returns: TIMESTAMPTZ
-- Lookup: AsOfInstant from related EvaluationContexts


CREATE OR REPLACE FUNCTION calc_stewardship_assignments_as_of_instant(p_stewardship_assignment_id TEXT)
RETURNS TIMESTAMPTZ AS $$
  SELECT (SELECT as_of_instant::timestamptz FROM evaluation_contexts WHERE evaluation_context_id = (SELECT evaluation_context FROM stewardship_assignments WHERE stewardship_assignment_id = p_stewardship_assignment_id));
$$ LANGUAGE sql STABLE;

-- calc_stewardship_assignments_name
-- Field: StewardshipAssignments.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_stewardship_assignments_name(p_stewardship_assignment_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(procedure_version, '') FROM stewardship_assignments WHERE stewardship_assignment_id = p_stewardship_assignment_id), ' / steward=', (SELECT NULLIF(steward_role, '') FROM stewardship_assignments WHERE stewardship_assignment_id = p_stewardship_assignment_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_stewardship_assignments_count_of_review_events
-- Field: StewardshipAssignments.CountOfReviewEvents
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_stewardship_assignments_count_of_review_events(p_stewardship_assignment_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM review_events WHERE procedure_version = (SELECT NULLIF(procedure_version, '') FROM stewardship_assignments WHERE stewardship_assignment_id = p_stewardship_assignment_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_stewardship_assignments_has_ever_been_reviewed
-- Field: StewardshipAssignments.HasEverBeenReviewed
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_stewardship_assignments_has_ever_been_reviewed(p_stewardship_assignment_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((calc_stewardship_assignments_count_of_review_events(p_stewardship_assignment_id))::NUMERIC, 0) > 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_stewardship_assignments_is_current_assignment
-- Field: StewardshipAssignments.IsCurrentAssignment
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_stewardship_assignments_is_current_assignment(p_stewardship_assignment_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_stewardship_assignments_as_of_instant(p_stewardship_assignment_id) AS val) SELECT ((COALESCE(COALESCE(((SELECT valid_from::timestamptz FROM stewardship_assignments WHERE stewardship_assignment_id = p_stewardship_assignment_id) <= (SELECT val FROM __erb_dedup_v1)), (((SELECT valid_from::timestamptz FROM stewardship_assignments WHERE stewardship_assignment_id = p_stewardship_assignment_id)) IS NULL AND ((SELECT val FROM __erb_dedup_v1)) IS NULL)), FALSE) AND COALESCE((COALESCE((SELECT valid_to::timestamptz FROM stewardship_assignments WHERE stewardship_assignment_id = p_stewardship_assignment_id) IS NULL, FALSE) OR COALESCE(COALESCE(((SELECT valid_to::timestamptz FROM stewardship_assignments WHERE stewardship_assignment_id = p_stewardship_assignment_id) > (SELECT val FROM __erb_dedup_v1)), FALSE), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

