RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_change_requests_is_my_decided_request(p_change_request_id), FALSE) AND COALESCE(NOT (COALESCE(calc_change_requests_is_implemented(p_change_request_id), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

