$$ LANGUAGE sql STABLE;

-- calc_recipients_is_sms_reachable
-- Field: Recipients.IsSmsReachable
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_recipients_is_sms_reachable(p_recipient_id TEXT)
RETURNS BOOLEAN AS $$
