RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(NOT (COALESCE(calc_recipients_is_sms_reachable(p_recipient_id), FALSE)), FALSE) AND COALESCE(NOT (COALESCE(calc_recipients_is_email_reachable(p_recipient_id), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

