RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_message_deliveries_is_failed_delivery(p_message_delivery_id), FALSE) AND COALESCE(NOT (COALESCE(calc_message_deliveries_is_triaged(p_message_delivery_id), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

