-- calc_authority_boundaries_ratifying_fragment_is_overdue
-- Field: AuthorityBoundaries.RatifyingFragmentIsOverdue
-- Type: lookup | DataType: boolean | Returns: BOOLEAN
-- Lookup: IsOverdueForReview from related KnowledgeFragments


CREATE OR REPLACE FUNCTION calc_authority_boundaries_ratifying_fragment_is_overdue(p_authority_boundary_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT calc_knowledge_fragments_is_overdue_for_review((SELECT ratified_by_knowledge_fragment FROM authority_boundaries WHERE authority_boundary_id = p_authority_boundary_id));
$$ LANGUAGE sql STABLE;

-- calc_authority_boundaries_ratifying_fragment_is_single_witness
-- Field: AuthorityBoundaries.RatifyingFragmentIsSingleWitness
-- Type: lookup | DataType: boolean | Returns: BOOLEAN
-- Lookup: IsFromSingleWitness from related KnowledgeFragments


CREATE OR REPLACE FUNCTION calc_authority_boundaries_ratifying_fragment_is_single_witness(p_authority_boundary_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT calc_knowledge_fragments_is_from_single_witness((SELECT ratified_by_knowledge_fragment FROM authority_boundaries WHERE authority_boundary_id = p_authority_boundary_id));
$$ LANGUAGE sql STABLE;

-- calc_authority_boundaries_ratifying_fragment_status
-- Field: AuthorityBoundaries.RatifyingFragmentStatus
-- Type: lookup | DataType: string | Returns: TEXT
-- Lookup: Status from related KnowledgeFragments


CREATE OR REPLACE FUNCTION calc_authority_boundaries_ratifying_fragment_status(p_authority_boundary_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT status::text FROM knowledge_fragments WHERE knowledge_fragment_id = (SELECT ratified_by_knowledge_fragment FROM authority_boundaries WHERE authority_boundary_id = p_authority_boundary_id));
$$ LANGUAGE sql STABLE;

-- calc_authority_boundaries_name
-- Field: AuthorityBoundaries.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_authority_boundaries_name(p_authority_boundary_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(forbidden_agent_kind, '') FROM authority_boundaries WHERE authority_boundary_id = p_authority_boundary_id), ' may not ', (SELECT NULLIF(forbidden_decision_kind, '') FROM authority_boundaries WHERE authority_boundary_id = p_authority_boundary_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_authority_boundaries_is_currently_binding
-- Field: AuthorityBoundaries.IsCurrentlyBinding
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_authority_boundaries_is_currently_binding(p_authority_boundary_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_authority_boundaries_as_of_instant(p_authority_boundary_id) AS val) SELECT ((COALESCE(COALESCE((SELECT NULLIF(status, '') FROM authority_boundaries WHERE authority_boundary_id = p_authority_boundary_id), '') = 'Approved', FALSE) AND COALESCE(COALESCE(((SELECT valid_from::timestamptz FROM authority_boundaries WHERE authority_boundary_id = p_authority_boundary_id) <= (SELECT val FROM __erb_dedup_v1)), (((SELECT valid_from::timestamptz FROM authority_boundaries WHERE authority_boundary_id = p_authority_boundary_id)) IS NULL AND ((SELECT val FROM __erb_dedup_v1)) IS NULL)), FALSE) AND COALESCE((COALESCE((SELECT valid_to::timestamptz FROM authority_boundaries WHERE authority_boundary_id = p_authority_boundary_id) IS NULL, FALSE) OR COALESCE(COALESCE(((SELECT valid_to::timestamptz FROM authority_boundaries WHERE authority_boundary_id = p_authority_boundary_id) > (SELECT val FROM __erb_dedup_v1)), FALSE), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_authority_boundaries_step_when_binding
-- Field: AuthorityBoundaries.StepWhenBinding
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_authority_boundaries_step_when_binding(p_authority_boundary_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_authority_boundaries_is_currently_binding(p_authority_boundary_id) THEN ((SELECT NULLIF(step, '') FROM authority_boundaries WHERE authority_boundary_id = p_authority_boundary_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_authority_boundaries_boundary_match_key
-- Field: AuthorityBoundaries.BoundaryMatchKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_authority_boundaries_boundary_match_key(p_authority_boundary_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(step, '') FROM authority_boundaries WHERE authority_boundary_id = p_authority_boundary_id), '|', (SELECT NULLIF(forbidden_agent_kind, '') FROM authority_boundaries WHERE authority_boundary_id = p_authority_boundary_id), '|', (SELECT NULLIF(forbidden_decision_kind, '') FROM authority_boundaries WHERE authority_boundary_id = p_authority_boundary_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_authority_boundaries_violation_count
-- Field: AuthorityBoundaries.ViolationCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_authority_boundaries_violation_count(p_authority_boundary_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM agent_decision_records WHERE calc_agent_decision_records_boundary_match_key(agent_decision_record_id) = calc_authority_boundaries_boundary_match_key(p_authority_boundary_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_authority_boundaries_is_untested
-- Field: AuthorityBoundaries.IsUntested
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_authority_boundaries_is_untested(p_authority_boundary_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_authority_boundaries_is_currently_binding(p_authority_boundary_id), FALSE) AND COALESCE(COALESCE((calc_authority_boundaries_violation_count(p_authority_boundary_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_authority_boundaries_has_ratifying_fragment
-- Field: AuthorityBoundaries.HasRatifyingFragment
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_authority_boundaries_has_ratifying_fragment(p_authority_boundary_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((SELECT NULLIF(ratified_by_knowledge_fragment, '') FROM authority_boundaries WHERE authority_boundary_id = p_authority_boundary_id) IS NOT NULL)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_authority_boundaries_is_unwarranted
-- Field: AuthorityBoundaries.IsUnwarranted
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_authority_boundaries_is_unwarranted(p_authority_boundary_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_authority_boundaries_is_currently_binding(p_authority_boundary_id), FALSE) AND COALESCE((COALESCE(NOT (COALESCE(calc_authority_boundaries_has_ratifying_fragment(p_authority_boundary_id), FALSE)), FALSE) OR COALESCE(NOT (COALESCE(calc_authority_boundaries_ratifying_fragment_is_valid(p_authority_boundary_id), FALSE)), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_authority_boundaries_warrant_is_thin
-- Field: AuthorityBoundaries.WarrantIsThin
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_authority_boundaries_warrant_is_thin(p_authority_boundary_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_authority_boundaries_is_currently_binding(p_authority_boundary_id), FALSE) AND COALESCE((COALESCE(calc_authority_boundaries_ratifying_fragment_is_overdue(p_authority_boundary_id), FALSE) OR COALESCE(calc_authority_boundaries_ratifying_fragment_is_single_witness(p_authority_boundary_id), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_authority_boundaries_is_unwarranted_and_untested
-- Field: AuthorityBoundaries.IsUnwarrantedAndUntested
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_authority_boundaries_is_unwarranted_and_untested(p_authority_boundary_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_authority_boundaries_is_unwarranted(p_authority_boundary_id), FALSE) AND COALESCE(calc_authority_boundaries_is_untested(p_authority_boundary_id), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_authority_boundaries_unwarranted_boundary_step_key
-- Field: AuthorityBoundaries.UnwarrantedBoundaryStepKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_authority_boundaries_unwarranted_boundary_step_key(p_authority_boundary_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_authority_boundaries_is_unwarranted(p_authority_boundary_id) THEN ((SELECT NULLIF(step, '') FROM authority_boundaries WHERE authority_boundary_id = p_authority_boundary_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_authority_boundaries_ratifying_fragment_key
-- Field: AuthorityBoundaries.RatifyingFragmentKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_authority_boundaries_ratifying_fragment_key(p_authority_boundary_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_authority_boundaries_is_currently_binding(p_authority_boundary_id) THEN ((SELECT NULLIF(ratified_by_knowledge_fragment, '') FROM authority_boundaries WHERE authority_boundary_id = p_authority_boundary_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_authority_boundaries_ratification_lapsed
-- Field: AuthorityBoundaries.RatificationLapsed
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_authority_boundaries_ratification_lapsed(p_authority_boundary_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_authority_boundaries_has_ratifying_fragment(p_authority_boundary_id), FALSE) AND COALESCE(NOT (COALESCE(calc_authority_boundaries_ratifying_fragment_is_valid(p_authority_boundary_id), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_authority_boundaries_binds_despite_lapsed_ratification
-- Field: AuthorityBoundaries.BindsDespiteLapsedRatification
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_authority_boundaries_binds_despite_lapsed_ratification(p_authority_boundary_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_authority_boundaries_is_currently_binding(p_authority_boundary_id), FALSE) AND COALESCE(calc_authority_boundaries_ratification_lapsed(p_authority_boundary_id), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_authority_boundaries_is_ungrounded_and_untested
-- Field: AuthorityBoundaries.IsUngroundedAndUntested
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_authority_boundaries_is_ungrounded_and_untested(p_authority_boundary_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_authority_boundaries_binds_despite_lapsed_ratification(p_authority_boundary_id), FALSE) AND COALESCE(calc_authority_boundaries_is_untested(p_authority_boundary_id), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_authority_boundaries_constrained_role_assignment_key
-- Field: AuthorityBoundaries.ConstrainedRoleAssignmentKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_authority_boundaries_constrained_role_assignment_key(p_authority_boundary_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_authority_boundaries_binds_despite_lapsed_ratification(p_authority_boundary_id) THEN ((SELECT NULLIF(authority_role, '') FROM authority_boundaries WHERE authority_boundary_id = p_authority_boundary_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_binding_observations_sla_minutes_at_run
-- Field: BindingObservations.SlaMinutesAtRun
-- Type: lookup | DataType: integer | Returns: INTEGER
-- Lookup: FreshnessSlaMinutes from related OperationalBindings


CREATE OR REPLACE FUNCTION calc_binding_observations_sla_minutes_at_run(p_binding_observation_id TEXT)
RETURNS INTEGER AS $$
  SELECT (SELECT freshness_sla_minutes::integer FROM operational_bindings WHERE operational_binding_id = (SELECT operational_binding FROM binding_observations WHERE binding_observation_id = p_binding_observation_id));
$$ LANGUAGE sql STABLE;

-- calc_binding_observations_is_authoritative_binding
-- Field: BindingObservations.IsAuthoritativeBinding
-- Type: lookup | DataType: boolean | Returns: BOOLEAN
-- Lookup: IsAuthoritative from related OperationalBindings


CREATE OR REPLACE FUNCTION calc_binding_observations_is_authoritative_binding(p_binding_observation_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (SELECT is_authoritative::boolean FROM operational_bindings WHERE operational_binding_id = (SELECT operational_binding FROM binding_observations WHERE binding_observation_id = p_binding_observation_id));
$$ LANGUAGE sql STABLE;

-- calc_binding_observations_name
-- Field: BindingObservations.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_binding_observations_name(p_binding_observation_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(step_execution, '') FROM binding_observations WHERE binding_observation_id = p_binding_observation_id), ' / ', (SELECT NULLIF(binding_observation_id, '') FROM binding_observations WHERE binding_observation_id = p_binding_observation_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_binding_observations_age_at_run_minutes
-- Field: BindingObservations.AgeAtRunMinutes
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_binding_observations_age_at_run_minutes(p_binding_observation_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((EXTRACT(EPOCH FROM (((SELECT read_at::timestamptz FROM binding_observations WHERE binding_observation_id = p_binding_observation_id))::timestamptz - ((SELECT observed_source_timestamp::timestamptz FROM binding_observations WHERE binding_observation_id = p_binding_observation_id))::timestamptz)) / 60))::integer;
$$ LANGUAGE sql STABLE;

-- calc_binding_observations_was_stale_at_run
-- Field: BindingObservations.WasStaleAtRun
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_binding_observations_was_stale_at_run(p_binding_observation_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_binding_observations_is_authoritative_binding(p_binding_observation_id), FALSE) AND COALESCE(COALESCE(calc_binding_observations_age_at_run_minutes(p_binding_observation_id), 0) > COALESCE(calc_binding_observations_sla_minutes_at_run(p_binding_observation_id), 0), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_binding_observations_stale_at_run_step_key
-- Field: BindingObservations.StaleAtRunStepKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_binding_observations_stale_at_run_step_key(p_binding_observation_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_binding_observations_was_stale_at_run(p_binding_observation_id) THEN ((SELECT NULLIF(step_execution, '') FROM binding_observations WHERE binding_observation_id = p_binding_observation_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_attestations_version_is_fit_now
-- Field: Attestations.VersionIsFitNow
-- Type: lookup | DataType: boolean | Returns: BOOLEAN
-- Lookup: ExecutedVersionIsFit from related ProcedureExecutions


CREATE OR REPLACE FUNCTION calc_attestations_version_is_fit_now(p_attestation_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT calc_procedure_executions_executed_version_is_fit((SELECT procedure_execution FROM attestations WHERE attestation_id = p_attestation_id));
$$ LANGUAGE sql STABLE;

-- calc_attestations_assurance_grade_now
-- Field: Attestations.AssuranceGradeNow
-- Type: lookup | DataType: string | Returns: TEXT
-- Lookup: AssuranceGrade from related ProcedureExecutions


CREATE OR REPLACE FUNCTION calc_attestations_assurance_grade_now(p_attestation_id TEXT)
RETURNS TEXT AS $$
  SELECT calc_procedure_executions_assurance_grade((SELECT procedure_execution FROM attestations WHERE attestation_id = p_attestation_id));
$$ LANGUAGE sql STABLE;

-- calc_attestations_name
-- Field: Attestations.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_attestations_name(p_attestation_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(procedure_execution, '') FROM attestations WHERE attestation_id = p_attestation_id), ' / ', (SELECT NULLIF(attestation_id, '') FROM attestations WHERE attestation_id = p_attestation_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_attestations_fitness_verdict_has_drifted
-- Field: Attestations.FitnessVerdictHasDrifted
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_attestations_fitness_verdict_has_drifted(p_attestation_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (NOT (COALESCE(COALESCE((SELECT version_was_fit_at_signing FROM attestations WHERE attestation_id = p_attestation_id), FALSE) = COALESCE(calc_attestations_version_is_fit_now(p_attestation_id), FALSE), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_attestations_assurance_grade_has_drifted
-- Field: Attestations.AssuranceGradeHasDrifted
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_attestations_assurance_grade_has_drifted(p_attestation_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (NOT (COALESCE(COALESCE((SELECT NULLIF(assurance_grade_at_signing, '') FROM attestations WHERE attestation_id = p_attestation_id), '') = COALESCE(calc_attestations_assurance_grade_now(p_attestation_id), ''), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_attestations_would_not_survive_restatement
-- Field: Attestations.WouldNotSurviveRestatement
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_attestations_would_not_survive_restatement(p_attestation_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_attestations_fitness_verdict_has_drifted(p_attestation_id), FALSE) OR COALESCE(calc_attestations_assurance_grade_has_drifted(p_attestation_id), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_app_role_profiles_name
-- Field: AppRoleProfiles.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_app_role_profiles_name(p_app_role_profile_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(display_label, '') FROM app_role_profiles WHERE app_role_profile_id = p_app_role_profile_id), ' (', (SELECT NULLIF(role_kind, '') FROM app_role_profiles WHERE app_role_profile_id = p_app_role_profile_id), ')'))::text;
$$ LANGUAGE sql STABLE;

-- calc_app_role_profiles_route_count
-- Field: AppRoleProfiles.RouteCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_app_role_profiles_route_count(p_app_role_profile_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM app_routes WHERE owning_role = (SELECT NULLIF(role, '') FROM app_role_profiles WHERE app_role_profile_id = p_app_role_profile_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_app_nav_groups_name
-- Field: AppNavGroups.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_app_nav_groups_name(p_app_nav_group_id TEXT)
