  SELECT ((SELECT COUNT(*) FROM rulebook_fields WHERE target_table = (SELECT NULLIF(rulebook_table_id, '') FROM rulebook_tables WHERE rulebook_table_id = p_rulebook_table_id) AND field_name = 'SemanticTypeIri'))::integer;
