RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM field_grants WHERE calc_field_grants_grant_key_when_readable(field_grant_id) = calc_role_schema_views_grant_key(p_role_schema_view_id)))::numeric;
