$$ LANGUAGE sql STABLE;

-- calc_vocabulary_terms_usage_count
-- Field: VocabularyTerms.UsageCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_vocabulary_terms_usage_count(p_vocabulary_term_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM requirements WHERE controlled_term = (SELECT NULLIF(vocabulary_term_id, '') FROM vocabulary_terms WHERE vocabulary_term_id = p_vocabulary_term_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_vocabulary_terms_is_orphan_term
-- Field: VocabularyTerms.IsOrphanTerm
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_vocabulary_terms_is_orphan_term(p_vocabulary_term_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((calc_vocabulary_terms_usage_count(p_vocabulary_term_id))::NUMERIC, 0) = 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_vocabulary_terms_is_widely_adopted_term
-- Field: VocabularyTerms.IsWidelyAdoptedTerm
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_vocabulary_terms_is_widely_adopted_term(p_vocabulary_term_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((calc_vocabulary_terms_usage_count(p_vocabulary_term_id))::NUMERIC, 0) >= 2)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_vocabulary_terms_orphan_term_vocabulary_key
-- Field: VocabularyTerms.OrphanTermVocabularyKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_vocabulary_terms_orphan_term_vocabulary_key(p_vocabulary_term_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_vocabulary_terms_is_orphan_term(p_vocabulary_term_id) THEN ((SELECT NULLIF(vocabulary, '') FROM vocabulary_terms WHERE vocabulary_term_id = p_vocabulary_term_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_vocabulary_terms_latest_meaning_change_at
-- Field: VocabularyTerms.LatestMeaningChangeAt
-- Type: aggregation | DataType: datetime | Returns: TIMESTAMPTZ


CREATE OR REPLACE FUNCTION calc_vocabulary_terms_latest_meaning_change_at(p_vocabulary_term_id TEXT)
RETURNS TIMESTAMPTZ AS $$
  SELECT ((SELECT MAX(changed_at) FROM term_meaning_changes WHERE vocabulary_term = p_vocabulary_term_id))::timestamptz;
$$ LANGUAGE sql STABLE;

-- calc_vocabulary_terms_has_stale_definition
-- Field: VocabularyTerms.HasStaleDefinition
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_vocabulary_terms_has_stale_definition(p_vocabulary_term_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_vocabulary_terms_latest_meaning_change_at(p_vocabulary_term_id) AS val) SELECT ((COALESCE((SELECT val FROM __erb_dedup_v1) IS NOT NULL, FALSE) AND COALESCE((COALESCE((SELECT definition_revised_at::timestamptz FROM vocabulary_terms WHERE vocabulary_term_id = p_vocabulary_term_id) IS NULL, FALSE) OR COALESCE(COALESCE(((SELECT definition_revised_at::timestamptz FROM vocabulary_terms WHERE vocabulary_term_id = p_vocabulary_term_id) < (SELECT val FROM __erb_dedup_v1)), FALSE), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_vocabulary_terms_structural_shift_count
-- Field: VocabularyTerms.StructuralShiftCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_vocabulary_terms_structural_shift_count(p_vocabulary_term_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM term_meaning_changes WHERE vocabulary_term = (SELECT NULLIF(vocabulary_term_id, '') FROM vocabulary_terms WHERE vocabulary_term_id = p_vocabulary_term_id) AND is_structural_change = TRUE AND (calc_term_meaning_changes_span_days(term_meaning_change_id))::numeric >= (700)::numeric))::integer;
$$ LANGUAGE sql STABLE;

-- calc_vocabulary_terms_has_structural_sense_shift_across_years
-- Field: VocabularyTerms.HasStructuralSenseShiftAcrossYears
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_vocabulary_terms_has_structural_sense_shift_across_years(p_vocabulary_term_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((calc_vocabulary_terms_structural_shift_count(p_vocabulary_term_id))::NUMERIC, 0) > 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_vocabulary_terms_pref_label_practitioner_mention_count
-- Field: VocabularyTerms.PrefLabelPractitionerMentionCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_vocabulary_terms_pref_label_practitioner_mention_count(p_vocabulary_term_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COALESCE(SUM((calc_term_label_variants_practitioner_mention_count(term_label_variant_id))::numeric), 0) FROM term_label_variants WHERE vocabulary_term = p_vocabulary_term_id AND label_kind = 'pref'))::integer;
$$ LANGUAGE sql STABLE;

-- calc_vocabulary_terms_alt_label_practitioner_mention_count
-- Field: VocabularyTerms.AltLabelPractitionerMentionCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_vocabulary_terms_alt_label_practitioner_mention_count(p_vocabulary_term_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COALESCE(SUM((calc_term_label_variants_practitioner_mention_count(term_label_variant_id))::numeric), 0) FROM term_label_variants WHERE vocabulary_term = p_vocabulary_term_id AND label_kind = 'alt'))::integer;
$$ LANGUAGE sql STABLE;

-- calc_vocabulary_terms_is_organized_around_official_term
-- Field: VocabularyTerms.IsOrganizedAroundOfficialTerm
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_vocabulary_terms_is_organized_around_official_term(p_vocabulary_term_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_vocabulary_terms_alt_label_practitioner_mention_count(p_vocabulary_term_id) AS val) SELECT ((COALESCE(COALESCE(((SELECT val FROM __erb_dedup_v1))::NUMERIC, 0) >= 2, FALSE) AND COALESCE(COALESCE((SELECT val FROM __erb_dedup_v1), 0) > COALESCE(calc_vocabulary_terms_pref_label_practitioner_mention_count(p_vocabulary_term_id), 0), FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_vocabulary_terms_source_phrasing_count
-- Field: VocabularyTerms.SourcePhrasingCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_vocabulary_terms_source_phrasing_count(p_vocabulary_term_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM source_term_mentions WHERE intended_term = (SELECT NULLIF(vocabulary_term_id, '') FROM vocabulary_terms WHERE vocabulary_term_id = p_vocabulary_term_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_vocabulary_terms_unreconciled_phrasing_count
-- Field: VocabularyTerms.UnreconciledPhrasingCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_vocabulary_terms_unreconciled_phrasing_count(p_vocabulary_term_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM source_term_mentions WHERE calc_source_term_mentions_unresolved_intended_term_key(source_term_mention_id) = (SELECT NULLIF(vocabulary_term_id, '') FROM vocabulary_terms WHERE vocabulary_term_id = p_vocabulary_term_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_vocabulary_terms_has_unreconciled_variant_phrasings
-- Field: VocabularyTerms.HasUnreconciledVariantPhrasings
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_vocabulary_terms_has_unreconciled_variant_phrasings(p_vocabulary_term_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((calc_vocabulary_terms_source_phrasing_count(p_vocabulary_term_id))::NUMERIC, 0) >= 2, FALSE) AND COALESCE(COALESCE((calc_vocabulary_terms_unreconciled_phrasing_count(p_vocabulary_term_id))::NUMERIC, 0) > 0, FALSE)));
$$ LANGUAGE sql STABLE;

