-- calc_step_variables_name
-- Field: StepVariables.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_step_variables_name(p_step_variable_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(step, '') FROM step_variables WHERE step_variable_id = p_step_variable_id), ' ', (SELECT NULLIF(direction, '') FROM step_variables WHERE step_variable_id = p_step_variable_id), ' ', (SELECT NULLIF(label, '') FROM step_variables WHERE step_variable_id = p_step_variable_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_step_variables_is_dangling_input
-- Field: StepVariables.IsDanglingInput
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_step_variables_is_dangling_input(p_step_variable_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(direction, '') FROM step_variables WHERE step_variable_id = p_step_variable_id), '') = 'Input', FALSE) AND COALESCE((SELECT NULLIF(source_variable, '') FROM step_variables WHERE step_variable_id = p_step_variable_id) IS NULL, FALSE) AND COALESCE(COALESCE((SELECT is_external_input FROM step_variables WHERE step_variable_id = p_step_variable_id), FALSE) = FALSE, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_step_variables_is_miswired_source
-- Field: StepVariables.IsMiswiredSource
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_step_variables_is_miswired_source(p_step_variable_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(source_variable, '') FROM step_variables WHERE step_variable_id = p_step_variable_id) IS NOT NULL, FALSE) AND COALESCE(COALESCE(calc_step_variables_source_direction(p_step_variable_id), '') <> 'Output', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_step_variables_consumer_count
-- Field: StepVariables.ConsumerCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_step_variables_consumer_count(p_step_variable_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM step_variables WHERE source_variable = (SELECT NULLIF(step_variable_id, '') FROM step_variables WHERE step_variable_id = p_step_variable_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_step_variables_input_step_key
-- Field: StepVariables.InputStepKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_step_variables_input_step_key(p_step_variable_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN COALESCE((SELECT NULLIF(direction, '') FROM step_variables WHERE step_variable_id = p_step_variable_id), '') = 'Input' THEN ((SELECT NULLIF(step, '') FROM step_variables WHERE step_variable_id = p_step_variable_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_step_variables_output_step_key
-- Field: StepVariables.OutputStepKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_step_variables_output_step_key(p_step_variable_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN COALESCE((SELECT NULLIF(direction, '') FROM step_variables WHERE step_variable_id = p_step_variable_id), '') = 'Output' THEN ((SELECT NULLIF(step, '') FROM step_variables WHERE step_variable_id = p_step_variable_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_step_variables_is_input_from_ai_artifact
-- Field: StepVariables.IsInputFromAiArtifact
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_step_variables_is_input_from_ai_artifact(p_step_variable_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(direction, '') FROM step_variables WHERE step_variable_id = p_step_variable_id), '') = 'Input', FALSE) AND COALESCE(COALESCE(calc_step_variables_source_step_agent_kind(p_step_variable_id), '') = 'AIAgent', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_step_variables_ai_artifact_consumer_has_no_accountable_age
-- Field: StepVariables.AiArtifactConsumerHasNoAccountableAgent
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_step_variables_ai_artifact_consumer_has_no_accountable_age(p_step_variable_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_step_variables_is_input_from_ai_artifact(p_step_variable_id), FALSE) AND COALESCE(calc_step_variables_step_accountable_agent(p_step_variable_id) IS NULL, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_step_variables_ai_blast_radius_path
-- Field: StepVariables.AiBlastRadiusPath
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_step_variables_ai_blast_radius_path(p_step_variable_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_step_variables_is_input_from_ai_artifact(p_step_variable_id) THEN (CONCAT(calc_step_variables_source_step_agent(p_step_variable_id), ' produces ', (SELECT NULLIF(label, '') FROM step_variables WHERE step_variable_id = p_step_variable_id), ' for ', (SELECT NULLIF(step, '') FROM step_variables WHERE step_variable_id = p_step_variable_id), '; role ', calc_step_variables_consumer_role(p_step_variable_id), '; agent ', calc_step_variables_step_accountable_agent(p_step_variable_id), '; workflow ', calc_step_variables_consumer_workflow(p_step_variable_id)))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

