-- calc_condition_checks_is_violated_invariant
-- Field: ConditionChecks.IsViolatedInvariant
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_condition_checks_is_violated_invariant(p_condition_check_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE(calc_condition_checks_condition_kind(p_condition_check_id), '') = 'Invariant', FALSE) AND COALESCE(COALESCE((SELECT held FROM condition_checks WHERE condition_check_id = p_condition_check_id), FALSE) = FALSE, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_condition_checks_failed_precondition_execution_key
