-- calc_level_capture_strategies_name
-- Field: LevelCaptureStrategies.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_level_capture_strategies_name(p_level_capture_strategy_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(level, '') FROM level_capture_strategies WHERE level_capture_strategy_id = p_level_capture_strategy_id), ' ', (SELECT NULLIF(knowledge_form, '') FROM level_capture_strategies WHERE level_capture_strategy_id = p_level_capture_strategy_id), ': ', LEFT(((SELECT NULLIF(description, '') FROM level_capture_strategies WHERE level_capture_strategy_id = p_level_capture_strategy_id))::text, (40)::integer)))::text;
$$ LANGUAGE sql STABLE;

-- calc_level_capture_strategies_contradicts_knowledge_form
-- Field: LevelCaptureStrategies.ContradictsKnowledgeForm
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_level_capture_strategies_contradicts_knowledge_form(p_level_capture_strategy_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((COALESCE(COALESCE((SELECT NULLIF(knowledge_form, '') FROM level_capture_strategies WHERE level_capture_strategy_id = p_level_capture_strategy_id), '') = 'Tacit', FALSE) AND COALESCE(COALESCE((SELECT NULLIF(transfer_mode, '') FROM level_capture_strategies WHERE level_capture_strategy_id = p_level_capture_strategy_id), '') = 'Codified', FALSE)), FALSE) OR COALESCE((COALESCE(COALESCE((SELECT NULLIF(knowledge_form, '') FROM level_capture_strategies WHERE level_capture_strategy_id = p_level_capture_strategy_id), '') = 'Explicit', FALSE) AND COALESCE(COALESCE((SELECT NULLIF(transfer_mode, '') FROM level_capture_strategies WHERE level_capture_strategy_id = p_level_capture_strategy_id), '') = 'InPerson', FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

