-- calc_tactical_resource_allocations_name
-- Field: TacticalResourceAllocations.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_tactical_resource_allocations_name(p_tactical_resource_allocation_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(step, '') FROM tactical_resource_allocations WHERE tactical_resource_allocation_id = p_tactical_resource_allocation_id), ' / ', (SELECT NULLIF(resource_label, '') FROM tactical_resource_allocations WHERE tactical_resource_allocation_id = p_tactical_resource_allocation_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_tactical_resource_allocations_utilization_percent
-- Field: TacticalResourceAllocations.UtilizationPercent
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_tactical_resource_allocations_utilization_percent(p_tactical_resource_allocation_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (CASE WHEN COALESCE(((SELECT available_units_per_week FROM tactical_resource_allocations WHERE tactical_resource_allocation_id = p_tactical_resource_allocation_id))::NUMERIC, 0) = 0 THEN (0)::text ELSE (ROUND(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT demanded_units_per_week FROM tactical_resource_allocations WHERE tactical_resource_allocation_id = p_tactical_resource_allocation_id)) AS v) __safe_numeric), 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE(100, 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT available_units_per_week FROM tactical_resource_allocations WHERE tactical_resource_allocation_id = p_tactical_resource_allocation_id)) AS v) __safe_numeric), 0), 0))) AS v) __safe_numeric), 0)))::NUMERIC, (1)::INTEGER))::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_tactical_resource_allocations_is_bottleneck
-- Field: TacticalResourceAllocations.IsBottleneck
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_tactical_resource_allocations_is_bottleneck(p_tactical_resource_allocation_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE(((SELECT demanded_units_per_week FROM tactical_resource_allocations WHERE tactical_resource_allocation_id = p_tactical_resource_allocation_id) > (SELECT available_units_per_week FROM tactical_resource_allocations WHERE tactical_resource_allocation_id = p_tactical_resource_allocation_id)), FALSE))::boolean;
$$ LANGUAGE sql STABLE;

