-- calc_collected_source_materials_is_modeled_before_organized
-- Field: CollectedSourceMaterials.IsModeledBeforeOrganized
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_collected_source_materials_is_modeled_before_organized(p_collected_source_material_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(encoded_into_version, '') FROM collected_source_materials WHERE collected_source_material_id = p_collected_source_material_id) IS NOT NULL, FALSE) AND COALESCE((COALESCE((SELECT organized_at::timestamptz FROM collected_source_materials WHERE collected_source_material_id = p_collected_source_material_id) IS NULL, FALSE) OR COALESCE(COALESCE(((SELECT encoded_at::timestamptz FROM collected_source_materials WHERE collected_source_material_id = p_collected_source_material_id) < (SELECT organized_at::timestamptz FROM collected_source_materials WHERE collected_source_material_id = p_collected_source_material_id)), FALSE), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_collected_source_materials_is_document_source
-- Field: CollectedSourceMaterials.IsDocumentSource
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_collected_source_materials_is_document_source(p_collected_source_material_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((SELECT NULLIF(material_kind, '') FROM collected_source_materials WHERE collected_source_material_id = p_collected_source_material_id), '') = 'DocumentExcerpt')::boolean;
$$ LANGUAGE sql STABLE;

-- calc_collected_source_materials_is_people_capture
-- Field: CollectedSourceMaterials.IsPeopleCapture
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_collected_source_materials_is_people_capture(p_collected_source_material_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(material_kind, '') FROM collected_source_materials WHERE collected_source_material_id = p_collected_source_material_id), '') = 'Transcript', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(material_kind, '') FROM collected_source_materials WHERE collected_source_material_id = p_collected_source_material_id), '') = 'FieldNotes', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_collected_source_materials_is_practice_evidence
-- Field: CollectedSourceMaterials.IsPracticeEvidence
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_collected_source_materials_is_practice_evidence(p_collected_source_material_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(material_kind, '') FROM collected_source_materials WHERE collected_source_material_id = p_collected_source_material_id), '') = 'FieldNotes', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(material_kind, '') FROM collected_source_materials WHERE collected_source_material_id = p_collected_source_material_id), '') = 'MinedEventTrace', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

