RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(from_term, '') FROM term_relations WHERE term_relation_id = p_term_relation_id), ' ', (SELECT NULLIF(relation_kind, '') FROM term_relations WHERE term_relation_id = p_term_relation_id), ' ', (SELECT NULLIF(to_term, '') FROM term_relations WHERE term_relation_id = p_term_relation_id)))::text;
