CREATE OR REPLACE FUNCTION calc_consumer_system_syncs_reaches_machines(p_consumer_system_sync_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_consumer_system_syncs_system_audience(p_consumer_system_sync_id) AS val) SELECT ((COALESCE(COALESCE((SELECT val FROM __erb_dedup_v1), '') = 'AI', FALSE) OR COALESCE(COALESCE((SELECT val FROM __erb_dedup_v1), '') = 'Both', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

