RETURNS BOOLEAN AS $$
  SELECT (COALESCE((calc_agent_integrations_pathway_integration_count(p_agent_integration_id))::NUMERIC, 0) <= 1)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_agent_integrations_is_deployed_on_ungoverned_graph
