-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_agent_integrations_is_deployed_on_ungoverned_graph(p_agent_integration_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(serves_snapshot, '') FROM agent_integrations WHERE agent_integration_id = p_agent_integration_id) IS NOT NULL, FALSE) AND COALESCE(COALESCE(calc_agent_integrations_snapshot_is_governed(p_agent_integration_id), FALSE) = FALSE, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_grounding_snapshots_name
-- Field: GroundingSnapshots.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_grounding_snapshots_name(p_grounding_snapshot_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT NULLIF(label, '') FROM grounding_snapshots WHERE grounding_snapshot_id = p_grounding_snapshot_id))::text;
$$ LANGUAGE sql STABLE;

-- calc_grounding_snapshots_is_governed
-- Field: GroundingSnapshots.IsGoverned
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_grounding_snapshots_is_governed(p_grounding_snapshot_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(steward_role, '') FROM grounding_snapshots WHERE grounding_snapshot_id = p_grounding_snapshot_id) IS NOT NULL, FALSE) AND COALESCE((SELECT governance_reviewed_at::timestamptz FROM grounding_snapshots WHERE grounding_snapshot_id = p_grounding_snapshot_id) IS NOT NULL, FALSE) AND COALESCE(COALESCE(((SELECT governance_reviewed_at::timestamptz FROM grounding_snapshots WHERE grounding_snapshot_id = p_grounding_snapshot_id) <= (SELECT served_from::timestamptz FROM grounding_snapshots WHERE grounding_snapshot_id = p_grounding_snapshot_id)), (((SELECT governance_reviewed_at::timestamptz FROM grounding_snapshots WHERE grounding_snapshot_id = p_grounding_snapshot_id)) IS NULL AND ((SELECT served_from::timestamptz FROM grounding_snapshots WHERE grounding_snapshot_id = p_grounding_snapshot_id)) IS NULL)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_grounding_snapshots_reasoner_run_count
-- Field: GroundingSnapshots.ReasonerRunCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_grounding_snapshots_reasoner_run_count(p_grounding_snapshot_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM reasoner_runs WHERE snapshot = (SELECT NULLIF(grounding_snapshot_id, '') FROM grounding_snapshots WHERE grounding_snapshot_id = p_grounding_snapshot_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_grounding_snapshots_consistent_reasoner_run_count
-- Field: GroundingSnapshots.ConsistentReasonerRunCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_grounding_snapshots_consistent_reasoner_run_count(p_grounding_snapshot_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM reasoner_runs WHERE snapshot = (SELECT NULLIF(grounding_snapshot_id, '') FROM grounding_snapshots WHERE grounding_snapshot_id = p_grounding_snapshot_id) AND is_consistent = TRUE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_grounding_snapshots_latest_materialized_at
-- Field: GroundingSnapshots.LatestMaterializedAt
-- Type: aggregation | DataType: datetime | Returns: TIMESTAMPTZ


CREATE OR REPLACE FUNCTION calc_grounding_snapshots_latest_materialized_at(p_grounding_snapshot_id TEXT)
RETURNS TIMESTAMPTZ AS $$
  SELECT ((SELECT MAX(materialized_at) FROM reasoner_runs WHERE snapshot = p_grounding_snapshot_id))::timestamptz;
$$ LANGUAGE sql STABLE;

-- calc_grounding_snapshots_served_without_consistency_check
-- Field: GroundingSnapshots.ServedWithoutConsistencyCheck
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_grounding_snapshots_served_without_consistency_check(p_grounding_snapshot_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT served_from::timestamptz FROM grounding_snapshots WHERE grounding_snapshot_id = p_grounding_snapshot_id) IS NOT NULL, FALSE) AND COALESCE(COALESCE((calc_grounding_snapshots_consistent_reasoner_run_count(p_grounding_snapshot_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_grounding_snapshots_served_before_materialization
-- Field: GroundingSnapshots.ServedBeforeMaterialization
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_grounding_snapshots_served_before_materialization(p_grounding_snapshot_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_grounding_snapshots_latest_materialized_at(p_grounding_snapshot_id) AS val) SELECT ((COALESCE((SELECT served_from::timestamptz FROM grounding_snapshots WHERE grounding_snapshot_id = p_grounding_snapshot_id) IS NOT NULL, FALSE) AND COALESCE((COALESCE((SELECT val FROM __erb_dedup_v1) IS NULL, FALSE) OR COALESCE(COALESCE(((SELECT val FROM __erb_dedup_v1) > (SELECT served_from::timestamptz FROM grounding_snapshots WHERE grounding_snapshot_id = p_grounding_snapshot_id)), FALSE), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_grounding_snapshots_assertion_count
-- Field: GroundingSnapshots.AssertionCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_grounding_snapshots_assertion_count(p_grounding_snapshot_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM snapshot_assertions WHERE snapshot = (SELECT NULLIF(grounding_snapshot_id, '') FROM grounding_snapshots WHERE grounding_snapshot_id = p_grounding_snapshot_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_grounding_snapshots_stale_assignment_assertion_count
-- Field: GroundingSnapshots.StaleAssignmentAssertionCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_grounding_snapshots_stale_assignment_assertion_count(p_grounding_snapshot_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM snapshot_assertions WHERE snapshot = (SELECT NULLIF(grounding_snapshot_id, '') FROM grounding_snapshots WHERE grounding_snapshot_id = p_grounding_snapshot_id) AND calc_snapshot_assertions_is_stale_role_assertion(snapshot_assertion_id) = TRUE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_grounding_snapshots_serves_stale_role_assignments
-- Field: GroundingSnapshots.ServesStaleRoleAssignments
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_grounding_snapshots_serves_stale_role_assignments(p_grounding_snapshot_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((calc_grounding_snapshots_stale_assignment_assertion_count(p_grounding_snapshot_id))::NUMERIC, 0) > 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_grounding_snapshots_deprecated_as_current_count
-- Field: GroundingSnapshots.DeprecatedAsCurrentCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_grounding_snapshots_deprecated_as_current_count(p_grounding_snapshot_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM snapshot_assertions WHERE snapshot = (SELECT NULLIF(grounding_snapshot_id, '') FROM grounding_snapshots WHERE grounding_snapshot_id = p_grounding_snapshot_id) AND calc_snapshot_assertions_presents_deprecated_as_current(snapshot_assertion_id) = TRUE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_grounding_snapshots_serves_deprecated_as_current
-- Field: GroundingSnapshots.ServesDeprecatedAsCurrent
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_grounding_snapshots_serves_deprecated_as_current(p_grounding_snapshot_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((calc_grounding_snapshots_deprecated_as_current_count(p_grounding_snapshot_id))::NUMERIC, 0) > 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_reasoner_runs_name
-- Field: ReasonerRuns.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_reasoner_runs_name(p_reasoner_run_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(snapshot, '') FROM reasoner_runs WHERE reasoner_run_id = p_reasoner_run_id), ' / ', (SELECT NULLIF(reasoner_profile, '') FROM reasoner_runs WHERE reasoner_run_id = p_reasoner_run_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_reasoner_runs_is_richness_tractability_failure
-- Field: ReasonerRuns.IsRichnessTractabilityFailure
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_reasoner_runs_is_richness_tractability_failure(p_reasoner_run_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE(((SELECT duration_seconds FROM reasoner_runs WHERE reasoner_run_id = p_reasoner_run_id) > (SELECT time_budget_seconds FROM reasoner_runs WHERE reasoner_run_id = p_reasoner_run_id)), FALSE), FALSE) OR COALESCE(COALESCE(((SELECT dropped_axiom_count FROM reasoner_runs WHERE reasoner_run_id = p_reasoner_run_id))::NUMERIC, 0) > 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_reasoner_runs_passes_schema_but_fails_reasoner
-- Field: ReasonerRuns.PassesSchemaButFailsReasoner
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_reasoner_runs_passes_schema_but_fails_reasoner(p_reasoner_run_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT schema_validation_passed FROM reasoner_runs WHERE reasoner_run_id = p_reasoner_run_id), FALSE), FALSE) AND COALESCE(COALESCE((SELECT is_consistent FROM reasoner_runs WHERE reasoner_run_id = p_reasoner_run_id), FALSE) = FALSE, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_snapshot_assertions_source_version_status
