RETURNS TEXT AS $$
  SELECT (SELECT status::text FROM procedure_versions WHERE procedure_version_id = (SELECT source_procedure_version FROM snapshot_assertions WHERE snapshot_assertion_id = p_snapshot_assertion_id));
$$ LANGUAGE sql STABLE;

-- calc_snapshot_assertions_source_assignment_is_current
-- Field: SnapshotAssertions.SourceAssignmentIsCurrent
-- Type: lookup | DataType: boolean | Returns: BOOLEAN
-- Lookup: IsCurrent from related RoleAssignments


CREATE OR REPLACE FUNCTION calc_snapshot_assertions_source_assignment_is_current(p_snapshot_assertion_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT calc_role_assignments_is_current((SELECT source_role_assignment FROM snapshot_assertions WHERE snapshot_assertion_id = p_snapshot_assertion_id));
$$ LANGUAGE sql STABLE;

-- calc_snapshot_assertions_snapshot_consistent_run_count
-- Field: SnapshotAssertions.SnapshotConsistentRunCount
-- Type: lookup | DataType: integer | Returns: INTEGER
-- Lookup: ConsistentReasonerRunCount from related GroundingSnapshots


CREATE OR REPLACE FUNCTION calc_snapshot_assertions_snapshot_consistent_run_count(p_snapshot_assertion_id TEXT)
RETURNS INTEGER AS $$
  SELECT calc_grounding_snapshots_consistent_reasoner_run_count((SELECT snapshot FROM snapshot_assertions WHERE snapshot_assertion_id = p_snapshot_assertion_id));
$$ LANGUAGE sql STABLE;

-- calc_snapshot_assertions_name
-- Field: SnapshotAssertions.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_snapshot_assertions_name(p_snapshot_assertion_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(subject_identifier, '') FROM snapshot_assertions WHERE snapshot_assertion_id = p_snapshot_assertion_id), ' ', (SELECT NULLIF(predicate, '') FROM snapshot_assertions WHERE snapshot_assertion_id = p_snapshot_assertion_id), ' ', (SELECT NULLIF(object_value, '') FROM snapshot_assertions WHERE snapshot_assertion_id = p_snapshot_assertion_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_snapshot_assertions_snapshot_is_reasoned
-- Field: SnapshotAssertions.SnapshotIsReasoned
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_snapshot_assertions_snapshot_is_reasoned(p_snapshot_assertion_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((calc_snapshot_assertions_snapshot_consistent_run_count(p_snapshot_assertion_id))::NUMERIC, 0) > 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_snapshot_assertions_is_stale_role_assertion
-- Field: SnapshotAssertions.IsStaleRoleAssertion
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_snapshot_assertions_is_stale_role_assertion(p_snapshot_assertion_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(source_role_assignment, '') FROM snapshot_assertions WHERE snapshot_assertion_id = p_snapshot_assertion_id) IS NOT NULL, FALSE) AND COALESCE(COALESCE(calc_snapshot_assertions_source_assignment_is_current(p_snapshot_assertion_id), FALSE) = FALSE, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_snapshot_assertions_presents_deprecated_as_current
-- Field: SnapshotAssertions.PresentsDeprecatedAsCurrent
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_snapshot_assertions_presents_deprecated_as_current(p_snapshot_assertion_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_snapshot_assertions_source_version_status(p_snapshot_assertion_id) AS val) SELECT ((COALESCE((COALESCE(COALESCE((SELECT val FROM __erb_dedup_v1), '') = 'Deprecated', FALSE) OR COALESCE(COALESCE((SELECT val FROM __erb_dedup_v1), '') = 'Archived', FALSE)), FALSE) AND COALESCE(COALESCE((SELECT NULLIF(presented_status, '') FROM snapshot_assertions WHERE snapshot_assertion_id = p_snapshot_assertion_id), '') = 'Current', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_snapshot_assertions_lacks_provenance
-- Field: SnapshotAssertions.LacksProvenance
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_snapshot_assertions_lacks_provenance(p_snapshot_assertion_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(provenance_uri, '') FROM snapshot_assertions WHERE snapshot_assertion_id = p_snapshot_assertion_id) IS NULL, FALSE) AND COALESCE((SELECT NULLIF(source_procedure_version, '') FROM snapshot_assertions WHERE snapshot_assertion_id = p_snapshot_assertion_id) IS NULL, FALSE) AND COALESCE((SELECT NULLIF(source_step, '') FROM snapshot_assertions WHERE snapshot_assertion_id = p_snapshot_assertion_id) IS NULL, FALSE) AND COALESCE((SELECT NULLIF(source_role_assignment, '') FROM snapshot_assertions WHERE snapshot_assertion_id = p_snapshot_assertion_id) IS NULL, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_snapshot_assertions_has_opaque_identifier
-- Field: SnapshotAssertions.HasOpaqueIdentifier
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_snapshot_assertions_has_opaque_identifier(p_snapshot_assertion_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE(LEFT(((SELECT NULLIF(subject_identifier, '') FROM snapshot_assertions WHERE snapshot_assertion_id = p_snapshot_assertion_id))::text, (9)::integer), '') = 'urn:uuid:', FALSE) OR COALESCE(COALESCE(LEFT(((SELECT NULLIF(subject_identifier, '') FROM snapshot_assertions WHERE snapshot_assertion_id = p_snapshot_assertion_id))::text, (2)::integer), '') = '_:', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_snapshot_assertions_lacks_dublin_core
-- Field: SnapshotAssertions.LacksDublinCore
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_snapshot_assertions_lacks_dublin_core(p_snapshot_assertion_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(dc_title, '') FROM snapshot_assertions WHERE snapshot_assertion_id = p_snapshot_assertion_id) IS NULL, FALSE) OR COALESCE((SELECT NULLIF(dc_description, '') FROM snapshot_assertions WHERE snapshot_assertion_id = p_snapshot_assertion_id) IS NULL, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

