-- calc_knowledge_query_definitions_source_system_count
-- Field: KnowledgeQueryDefinitions.SourceSystemCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_knowledge_query_definitions_source_system_count(p_knowledge_query_definition_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM knowledge_query_sources WHERE query_definition = (SELECT NULLIF(knowledge_query_definition_id, '') FROM knowledge_query_definitions WHERE knowledge_query_definition_id = p_knowledge_query_definition_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_query_definitions_misses_a_layer
-- Field: KnowledgeQueryDefinitions.MissesALayer
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_query_definitions_misses_a_layer(p_knowledge_query_definition_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT needs_ontology_and_instances FROM knowledge_query_definitions WHERE knowledge_query_definition_id = p_knowledge_query_definition_id), FALSE), FALSE) AND COALESCE((COALESCE(COALESCE((SELECT traverses_ontology_layer FROM knowledge_query_definitions WHERE knowledge_query_definition_id = p_knowledge_query_definition_id), FALSE) = FALSE, FALSE) OR COALESCE(COALESCE((SELECT traverses_instance_layer FROM knowledge_query_definitions WHERE knowledge_query_definition_id = p_knowledge_query_definition_id), FALSE) = FALSE, FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_query_definitions_consolidated_distributed_sourc
-- Field: KnowledgeQueryDefinitions.ConsolidatedDistributedSources
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_query_definitions_consolidated_distributed_sourc(p_knowledge_query_definition_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((calc_knowledge_query_definitions_source_system_count(p_knowledge_query_definition_id))::NUMERIC, 0) > 1, FALSE) AND COALESCE(COALESCE((SELECT ran_over_consolidated_copy FROM knowledge_query_definitions WHERE knowledge_query_definition_id = p_knowledge_query_definition_id), FALSE), FALSE)));
$$ LANGUAGE sql STABLE;

-- get_knowledge_query_definitions_label
