CREATE OR REPLACE FUNCTION get_knowledge_query_definitions_label(p_knowledge_query_definition_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT label FROM knowledge_query_definitions WHERE knowledge_query_definition_id = p_knowledge_query_definition_id);
