-- calc_answer_groundings_name
-- Field: AnswerGroundings.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_answer_groundings_name(p_answer_grounding_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(assistant_answer, '') FROM answer_groundings WHERE answer_grounding_id = p_answer_grounding_id), ' <- ', (SELECT NULLIF(snapshot_assertion, '') FROM answer_groundings WHERE answer_grounding_id = p_answer_grounding_id), (SELECT NULLIF(retrieval_segment, '') FROM answer_groundings WHERE answer_grounding_id = p_answer_grounding_id), (SELECT NULLIF(external_source_uri, '') FROM answer_groundings WHERE answer_grounding_id = p_answer_grounding_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_answer_groundings_is_from_own_knowledge
-- Field: AnswerGroundings.IsFromOwnKnowledge
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_answer_groundings_is_from_own_knowledge(p_answer_grounding_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(external_source_uri, '') FROM answer_groundings WHERE answer_grounding_id = p_answer_grounding_id) IS NULL, FALSE) AND COALESCE((COALESCE((SELECT NULLIF(snapshot_assertion, '') FROM answer_groundings WHERE answer_grounding_id = p_answer_grounding_id) IS NOT NULL, FALSE) OR COALESCE((SELECT NULLIF(retrieval_segment, '') FROM answer_groundings WHERE answer_grounding_id = p_answer_grounding_id) IS NOT NULL, FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_answer_groundings_grounds_on_stale_assertion
-- Field: AnswerGroundings.GroundsOnStaleAssertion
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_answer_groundings_grounds_on_stale_assertion(p_answer_grounding_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(snapshot_assertion, '') FROM answer_groundings WHERE answer_grounding_id = p_answer_grounding_id) IS NOT NULL, FALSE) AND COALESCE((COALESCE(calc_answer_groundings_assertion_is_stale(p_answer_grounding_id), FALSE) OR COALESCE(calc_answer_groundings_assertion_presents_deprecated(p_answer_grounding_id), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_answer_requirement_checks_name
-- Field: AnswerRequirementChecks.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_answer_requirement_checks_name(p_answer_requirement_check_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(assistant_answer, '') FROM answer_requirement_checks WHERE answer_requirement_check_id = p_answer_requirement_check_id), ' vs ', (SELECT NULLIF(requirement, '') FROM answer_requirement_checks WHERE answer_requirement_check_id = p_answer_requirement_check_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_ai_tool_invocations_executed_step
-- Field: AiToolInvocations.ExecutedStep
-- Type: lookup | DataType: string | Returns: TEXT
-- Lookup: Step from related StepExecutions


CREATE OR REPLACE FUNCTION calc_ai_tool_invocations_executed_step(p_ai_tool_invocation_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT step::text FROM step_executions WHERE step_execution_id = (SELECT step_execution FROM ai_tool_invocations WHERE ai_tool_invocation_id = p_ai_tool_invocation_id));
$$ LANGUAGE sql STABLE;

-- calc_ai_tool_invocations_declared_input_count
-- Field: AiToolInvocations.DeclaredInputCount
-- Type: lookup | DataType: integer | Returns: INTEGER
-- Lookup: StepInputVariableCount from related StepExecutions


CREATE OR REPLACE FUNCTION calc_ai_tool_invocations_declared_input_count(p_ai_tool_invocation_id TEXT)
RETURNS INTEGER AS $$
  SELECT calc_step_executions_step_input_variable_count((SELECT step_execution FROM ai_tool_invocations WHERE ai_tool_invocation_id = p_ai_tool_invocation_id));
$$ LANGUAGE sql STABLE;

-- calc_ai_tool_invocations_name
-- Field: AiToolInvocations.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_ai_tool_invocations_name(p_ai_tool_invocation_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(invoking_agent, '') FROM ai_tool_invocations WHERE ai_tool_invocation_id = p_ai_tool_invocation_id), ' -> ', (SELECT NULLIF(function, '') FROM ai_tool_invocations WHERE ai_tool_invocation_id = p_ai_tool_invocation_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_ai_tool_invocations_declared_function_count
-- Field: AiToolInvocations.DeclaredFunctionCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_ai_tool_invocations_declared_function_count(p_ai_tool_invocation_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM step_functions WHERE step = calc_ai_tool_invocations_executed_step(p_ai_tool_invocation_id) AND function = (SELECT NULLIF(function, '') FROM ai_tool_invocations WHERE ai_tool_invocation_id = p_ai_tool_invocation_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_ai_tool_invocations_is_undeclared_tool_use
-- Field: AiToolInvocations.IsUndeclaredToolUse
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_ai_tool_invocations_is_undeclared_tool_use(p_ai_tool_invocation_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((calc_ai_tool_invocations_declared_function_count(p_ai_tool_invocation_id))::NUMERIC, 0) = 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_ai_tool_invocations_acted_without_declared_context
-- Field: AiToolInvocations.ActedWithoutDeclaredContext
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_ai_tool_invocations_acted_without_declared_context(p_ai_tool_invocation_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_ai_tool_invocations_declared_input_count(p_ai_tool_invocation_id) AS val) SELECT ((COALESCE(COALESCE(((SELECT val FROM __erb_dedup_v1))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((SELECT supplied_input_count FROM ai_tool_invocations WHERE ai_tool_invocation_id = p_ai_tool_invocation_id), 0) < COALESCE((SELECT val FROM __erb_dedup_v1), 0), FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_embedding_probes_name
-- Field: EmbeddingProbes.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_embedding_probes_name(p_embedding_probe_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(term_a, '') FROM embedding_probes WHERE embedding_probe_id = p_embedding_probe_id), ' / ', (SELECT NULLIF(term_b, '') FROM embedding_probes WHERE embedding_probe_id = p_embedding_probe_id), ' @ ', (SELECT NULLIF(embedding_model, '') FROM embedding_probes WHERE embedding_probe_id = p_embedding_probe_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_embedding_probes_synonyms_not_similar
-- Field: EmbeddingProbes.SynonymsNotSimilar
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_embedding_probes_synonyms_not_similar(p_embedding_probe_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(expected_relation, '') FROM embedding_probes WHERE embedding_probe_id = p_embedding_probe_id), '') = 'NearSynonym', FALSE) AND COALESCE(COALESCE(((SELECT cosine_similarity FROM embedding_probes WHERE embedding_probe_id = p_embedding_probe_id))::NUMERIC, 0) < 0.7, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_embedding_probes_opposites_not_opposed
-- Field: EmbeddingProbes.OppositesNotOpposed
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_embedding_probes_opposites_not_opposed(p_embedding_probe_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(expected_relation, '') FROM embedding_probes WHERE embedding_probe_id = p_embedding_probe_id), '') = 'Opposite', FALSE) AND COALESCE(COALESCE(((SELECT cosine_similarity FROM embedding_probes WHERE embedding_probe_id = p_embedding_probe_id))::NUMERIC, 0) > 0.3, FALSE)));
$$ LANGUAGE sql STABLE;

