  SELECT ((COALESCE(COALESCE((SELECT NULLIF(automation_level, '') FROM ai_adoption_initiatives WHERE ai_adoption_initiative_id = p_ai_adoption_initiative_id), '') = 'Full', FALSE) AND COALESCE((COALESCE((SELECT NULLIF(preceding_initiative, '') FROM ai_adoption_initiatives WHERE ai_adoption_initiative_id = p_ai_adoption_initiative_id) IS NULL, FALSE) OR COALESCE(COALESCE((calc_ai_adoption_initiatives_preceding_reviewed_output_count(p_ai_adoption_initiative_id))::NUMERIC, 0) = 0, FALSE)), FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_ai_adoption_initiatives_underinvests_knowledge_layer
-- Field: AiAdoptionInitiatives.UnderinvestsKnowledgeLayer
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_ai_adoption_initiatives_underinvests_knowledge_layer(p_ai_adoption_initiative_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE(((SELECT model_layer_budget FROM ai_adoption_initiatives WHERE ai_adoption_initiative_id = p_ai_adoption_initiative_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE(((SELECT knowledge_layer_budget FROM ai_adoption_initiatives WHERE ai_adoption_initiative_id = p_ai_adoption_initiative_id) < (SELECT model_layer_budget FROM ai_adoption_initiatives WHERE ai_adoption_initiative_id = p_ai_adoption_initiative_id)), FALSE), FALSE)));
$$ LANGUAGE sql STABLE;

