RETURNS NUMERIC AS $$
  SELECT (SELECT knowledge_access_score::numeric FROM knowledge_outcome_measurements WHERE knowledge_outcome_measurement_id = (SELECT comparison_baseline FROM knowledge_outcome_measurements WHERE knowledge_outcome_measurement_id = p_knowledge_outcome_measurement_id));
