CREATE OR REPLACE FUNCTION calc_governed_models_name(p_governed_model_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT NULLIF(label, '') FROM governed_models WHERE governed_model_id = p_governed_model_id))::text;
$$ LANGUAGE sql STABLE;

-- calc_governed_models_days_since_registered
-- Field: GovernedModels.DaysSinceRegistered
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_governed_models_days_since_registered(p_governed_model_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((((calc_governed_models_as_of_instant(p_governed_model_id))::timestamptz AT TIME ZONE 'UTC')::date - (((SELECT registered_at::timestamptz FROM governed_models WHERE governed_model_id = p_governed_model_id))::timestamptz AT TIME ZONE 'UTC')::date))::integer;
$$ LANGUAGE sql STABLE;

-- calc_governed_models_charter_count
-- Field: GovernedModels.CharterCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_governed_models_charter_count(p_governed_model_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM model_charters WHERE governed_model = (SELECT NULLIF(governed_model_id, '') FROM governed_models WHERE governed_model_id = p_governed_model_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_governed_models_current_charter_count
-- Field: GovernedModels.CurrentCharterCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_governed_models_current_charter_count(p_governed_model_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM model_charters WHERE governed_model = (SELECT NULLIF(governed_model_id, '') FROM governed_models WHERE governed_model_id = p_governed_model_id) AND calc_model_charters_is_current(model_charter_id) = TRUE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_governed_models_is_ownerless
-- Field: GovernedModels.IsOwnerless
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_governed_models_is_ownerless(p_governed_model_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((calc_governed_models_current_charter_count(p_governed_model_id))::NUMERIC, 0) = 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_governed_models_is_ownerless_past_a_year
-- Field: GovernedModels.IsOwnerlessPastAYear
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_governed_models_is_ownerless_past_a_year(p_governed_model_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_governed_models_is_ownerless(p_governed_model_id), FALSE) AND COALESCE(COALESCE((calc_governed_models_days_since_registered(p_governed_model_id))::NUMERIC, 0) > 365, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_governed_models_governance_lapsed
-- Field: GovernedModels.GovernanceLapsed
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_governed_models_governance_lapsed(p_governed_model_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((calc_governed_models_charter_count(p_governed_model_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((calc_governed_models_current_charter_count(p_governed_model_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_governed_models_has_no_current_steward
