RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_governed_models_is_unmaintained(p_governed_model_id), FALSE) OR COALESCE(COALESCE((calc_governed_models_documents_behind_count(p_governed_model_id))::NUMERIC, 0) > 0, FALSE)));
$$ LANGUAGE sql STABLE;

