-- calc_governed_models_lacks_lifecycle_stage_control
-- Field: GovernedModels.LacksLifecycleStageControl
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_governed_models_lacks_lifecycle_stage_control(p_governed_model_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(model_kind, '') FROM governed_models WHERE governed_model_id = p_governed_model_id), '') = 'ProcedureFamily', FALSE) AND COALESCE((COALESCE(COALESCE((calc_governed_models_collection_control_count(p_governed_model_id))::NUMERIC, 0) = 0, FALSE) OR COALESCE(COALESCE((calc_governed_models_stewardship_control_count(p_governed_model_id))::NUMERIC, 0) = 0, FALSE) OR COALESCE(COALESCE((calc_governed_models_retrieval_control_count(p_governed_model_id))::NUMERIC, 0) = 0, FALSE) OR COALESCE(COALESCE((calc_governed_models_use_control_count(p_governed_model_id))::NUMERIC, 0) = 0, FALSE)), FALSE)));
$$ LANGUAGE sql STABLE;

