  SELECT ((COALESCE(COALESCE((SELECT NULLIF(model_kind, '') FROM governed_models WHERE governed_model_id = p_governed_model_id), '') = 'ProcedureFamily', FALSE) AND COALESCE(COALESCE((calc_governed_models_continuous_pipeline_stage_count(p_governed_model_id))::NUMERIC, 0) < 3, FALSE)));
$$ LANGUAGE sql STABLE;

