  SELECT ((COALESCE(COALESCE((SELECT NULLIF(model_kind, '') FROM governed_models WHERE governed_model_id = p_governed_model_id), '') <> 'Vocabulary', FALSE) AND COALESCE(COALESCE((calc_governed_models_real_data_mapping_run_count(p_governed_model_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

