-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_model_change_requests_authority_review_skipped(p_model_change_request_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_model_change_requests_requires_authority_review(p_model_change_request_id), FALSE) AND COALESCE(calc_model_change_requests_is_accepted(p_model_change_request_id), FALSE) AND COALESCE(COALESCE(calc_model_change_requests_has_authority_review(p_model_change_request_id), FALSE) = FALSE, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

