RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM expected_inference_checks WHERE change_validation_run = (SELECT NULLIF(change_validation_run_id, '') FROM change_validation_runs WHERE change_validation_run_id = p_change_validation_run_id)))::integer;
