CREATE OR REPLACE FUNCTION calc_model_expansion_requests_name(p_model_expansion_request_id TEXT)
RETURNS TEXT AS $$
  SELECT (LEFT(((SELECT NULLIF(workflow_description, '') FROM model_expansion_requests WHERE model_expansion_request_id = p_model_expansion_request_id))::text, (60)::integer))::text;
$$ LANGUAGE sql STABLE;

-- calc_model_expansion_requests_concept_count
-- Field: ModelExpansionRequests.ConceptCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_model_expansion_requests_concept_count(p_model_expansion_request_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM expansion_concept_fits WHERE model_expansion_request = (SELECT NULLIF(model_expansion_request_id, '') FROM model_expansion_requests WHERE model_expansion_request_id = p_model_expansion_request_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_model_expansion_requests_uncovered_concept_count
-- Field: ModelExpansionRequests.UncoveredConceptCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_model_expansion_requests_uncovered_concept_count(p_model_expansion_request_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM expansion_concept_fits WHERE model_expansion_request = (SELECT NULLIF(model_expansion_request_id, '') FROM model_expansion_requests WHERE model_expansion_request_id = p_model_expansion_request_id) AND calc_expansion_concept_fits_is_uncovered(expansion_concept_fit_id) = TRUE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_model_expansion_requests_is_cross_function_expansion
-- Field: ModelExpansionRequests.IsCrossFunctionExpansion
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_model_expansion_requests_is_cross_function_expansion(p_model_expansion_request_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_model_expansion_requests_model_domain_owner(p_model_expansion_request_id) AS val) SELECT ((COALESCE((SELECT NULLIF(requesting_organization, '') FROM model_expansion_requests WHERE model_expansion_request_id = p_model_expansion_request_id) IS NOT NULL, FALSE) AND COALESCE((SELECT val FROM __erb_dedup_v1) IS NOT NULL, FALSE) AND COALESCE(COALESCE((SELECT NULLIF(requesting_organization, '') FROM model_expansion_requests WHERE model_expansion_request_id = p_model_expansion_request_id), '') <> COALESCE((SELECT val FROM __erb_dedup_v1), ''), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_model_expansion_requests_requires_schema_extension
-- Field: ModelExpansionRequests.RequiresSchemaExtension
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_model_expansion_requests_requires_schema_extension(p_model_expansion_request_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((calc_model_expansion_requests_uncovered_concept_count(p_model_expansion_request_id))::NUMERIC, 0) > 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_model_expansion_requests_fit_decision_contradicts_concept_
-- Field: ModelExpansionRequests.FitDecisionContradictsConceptFit
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_model_expansion_requests_fit_decision_contradicts_concept_(p_model_expansion_request_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(fit_decision, '') FROM model_expansion_requests WHERE model_expansion_request_id = p_model_expansion_request_id), '') = 'FitsExistingSchema', FALSE) AND COALESCE(COALESCE((calc_model_expansion_requests_uncovered_concept_count(p_model_expansion_request_id))::NUMERIC, 0) > 0, FALSE)));
$$ LANGUAGE sql STABLE;

