CREATE OR REPLACE FUNCTION calc_competency_question_set_entries_as_of_instant(p_competency_question_set_entry_id TEXT)
RETURNS TIMESTAMPTZ AS $$
  SELECT (SELECT as_of_instant::timestamptz FROM evaluation_contexts WHERE evaluation_context_id = (SELECT evaluation_context FROM competency_question_set_entries WHERE competency_question_set_entry_id = p_competency_question_set_entry_id));
$$ LANGUAGE sql STABLE;

-- calc_competency_question_set_entries_name
-- Field: CompetencyQuestionSetEntries.Name
