RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(governed_model, '') FROM competency_question_set_entries WHERE competency_question_set_entry_id = p_competency_question_set_entry_id), ' / ', (SELECT NULLIF(role_question, '') FROM competency_question_set_entries WHERE competency_question_set_entry_id = p_competency_question_set_entry_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_competency_question_set_entries_days_since_added
-- Field: CompetencyQuestionSetEntries.DaysSinceAdded
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_competency_question_set_entries_days_since_added(p_competency_question_set_entry_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((((calc_competency_question_set_entries_as_of_instant(p_competency_question_set_entry_id))::timestamptz AT TIME ZONE 'UTC')::date - (((SELECT added_at::timestamptz FROM competency_question_set_entries WHERE competency_question_set_entry_id = p_competency_question_set_entry_id))::timestamptz AT TIME ZONE 'UTC')::date))::integer;
$$ LANGUAGE sql STABLE;

-- calc_competency_question_set_entries_is_outgrown_baseline_quest
-- Field: CompetencyQuestionSetEntries.IsOutgrownBaselineQuestion
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_competency_question_set_entries_is_outgrown_baseline_quest(p_competency_question_set_entry_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT is_original_baseline FROM competency_question_set_entries WHERE competency_question_set_entry_id = p_competency_question_set_entry_id), FALSE), FALSE) AND COALESCE(COALESCE((calc_competency_question_set_entries_days_since_added(p_competency_question_set_entry_id))::NUMERIC, 0) > 365, FALSE) AND COALESCE(COALESCE((SELECT NULLIF(relevance_verdict, '') FROM competency_question_set_entries WHERE competency_question_set_entry_id = p_competency_question_set_entry_id), '') = 'NoLongerRelevant', FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_competency_question_set_entries_irrelevant_but_still_activ
-- Field: CompetencyQuestionSetEntries.IrrelevantButStillActive
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_competency_question_set_entries_irrelevant_but_still_activ(p_competency_question_set_entry_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(relevance_verdict, '') FROM competency_question_set_entries WHERE competency_question_set_entry_id = p_competency_question_set_entry_id), '') = 'NoLongerRelevant', FALSE) AND COALESCE(COALESCE((SELECT NULLIF(status, '') FROM competency_question_set_entries WHERE competency_question_set_entry_id = p_competency_question_set_entry_id), '') = 'Active', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_competency_question_set_entries_governance_use_count
-- Field: CompetencyQuestionSetEntries.GovernanceUseCount
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_competency_question_set_entries_governance_use_count(p_competency_question_set_entry_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE((SELECT used_for_scoping FROM competency_question_set_entries WHERE competency_question_set_entry_id = p_competency_question_set_entry_id), FALSE) THEN (1)::text ELSE (0)::text END) AS v) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE((SELECT used_as_acceptance_criterion FROM competency_question_set_entries WHERE competency_question_set_entry_id = p_competency_question_set_entry_id), FALSE) THEN (1)::text ELSE (0)::text END) AS v) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE((SELECT used_as_test_driver FROM competency_question_set_entries WHERE competency_question_set_entry_id = p_competency_question_set_entry_id), FALSE) THEN (1)::text ELSE (0)::text END) AS v) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE((SELECT used_for_governance FROM competency_question_set_entries WHERE competency_question_set_entry_id = p_competency_question_set_entry_id), FALSE) THEN (1)::text ELSE (0)::text END) AS v) __safe_numeric), 0))) AS v) __safe_numeric), 0))) AS v) __safe_numeric), 0)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_competency_question_set_entries_serves_every_governance_us
-- Field: CompetencyQuestionSetEntries.ServesEveryGovernanceUse
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_competency_question_set_entries_serves_every_governance_us(p_competency_question_set_entry_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((calc_competency_question_set_entries_governance_use_count(p_competency_question_set_entry_id))::NUMERIC, 0) = 4)::boolean;
$$ LANGUAGE sql STABLE;

