  SELECT (CONCAT((SELECT NULLIF(step, '') FROM assignment_instant_checks WHERE assignment_instant_check_id = p_assignment_instant_check_id), ' / ', (SELECT NULLIF(role_assignment, '') FROM assignment_instant_checks WHERE assignment_instant_check_id = p_assignment_instant_check_id)))::text;
