CREATE OR REPLACE FUNCTION calc_governance_stage_controls_name(p_governance_stage_control_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(governed_model, '') FROM governance_stage_controls WHERE governance_stage_control_id = p_governance_stage_control_id), ' ', (SELECT NULLIF(stage, '') FROM governance_stage_controls WHERE governance_stage_control_id = p_governance_stage_control_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_governance_stage_controls_is_continuous_pipeline_stage
-- Field: GovernanceStageControls.IsContinuousPipelineStage
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_governance_stage_controls_is_continuous_pipeline_stage(p_governance_stage_control_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((COALESCE(COALESCE((SELECT NULLIF(stage, '') FROM governance_stage_controls WHERE governance_stage_control_id = p_governance_stage_control_id), '') = 'Collection', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(stage, '') FROM governance_stage_controls WHERE governance_stage_control_id = p_governance_stage_control_id), '') = 'Organization', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(stage, '') FROM governance_stage_controls WHERE governance_stage_control_id = p_governance_stage_control_id), '') = 'Encoding', FALSE)), FALSE) AND COALESCE(COALESCE((SELECT is_continuous FROM governance_stage_controls WHERE governance_stage_control_id = p_governance_stage_control_id), FALSE), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_process_design_decisions_name
