  SELECT ((COALESCE(COALESCE((SELECT NULLIF(change_layer, '') FROM model_change_log_entries WHERE model_change_log_entry_id = p_model_change_log_entry_id), '') = 'Schema', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(change_layer, '') FROM model_change_log_entries WHERE model_change_log_entry_id = p_model_change_log_entry_id), '') = 'Vocabulary', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

