RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(change_operation, '') FROM model_change_log_entries WHERE model_change_log_entry_id = p_model_change_log_entry_id), '') = 'RemoveClass', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(change_operation, '') FROM model_change_log_entries WHERE model_change_log_entry_id = p_model_change_log_entry_id), '') = 'RenameClass', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_model_change_log_entries_is_invalidating_domain_range_chan
