CREATE OR REPLACE FUNCTION calc_model_change_log_entries_is_invalidating_domain_range_chan(p_model_change_log_entry_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(change_operation, '') FROM model_change_log_entries WHERE model_change_log_entry_id = p_model_change_log_entry_id), '') = 'ChangeDomainRange', FALSE) AND COALESCE(COALESCE((SELECT invalidates_instances FROM model_change_log_entries WHERE model_change_log_entry_id = p_model_change_log_entry_id), FALSE), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_model_change_log_entries_is_inconsistent_disjointness
