CREATE OR REPLACE FUNCTION calc_model_change_log_entries_is_backward_incompatible(p_model_change_log_entry_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_model_change_log_entries_is_class_removal_or_rename(p_model_change_log_entry_id), FALSE) OR COALESCE(COALESCE((SELECT invalidates_instances FROM model_change_log_entries WHERE model_change_log_entry_id = p_model_change_log_entry_id), FALSE), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_model_change_log_entries_is_additive_schema_change
