-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_model_change_log_entries_is_additive_schema_change(p_model_change_log_entry_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(change_layer, '') FROM model_change_log_entries WHERE model_change_log_entry_id = p_model_change_log_entry_id), '') = 'Schema', FALSE) AND COALESCE((COALESCE(COALESCE((SELECT NULLIF(change_operation, '') FROM model_change_log_entries WHERE model_change_log_entry_id = p_model_change_log_entry_id), '') = 'AddClass', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(change_operation, '') FROM model_change_log_entries WHERE model_change_log_entry_id = p_model_change_log_entry_id), '') = 'AddProperty', FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_model_change_log_entries_is_unexplained_modification
-- Field: ModelChangeLogEntries.IsUnexplainedModification
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_model_change_log_entries_is_unexplained_modification(p_model_change_log_entry_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((COALESCE(COALESCE((SELECT NULLIF(change_layer, '') FROM model_change_log_entries WHERE model_change_log_entry_id = p_model_change_log_entry_id), '') = 'Schema', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(change_layer, '') FROM model_change_log_entries WHERE model_change_log_entry_id = p_model_change_log_entry_id), '') = 'Instance', FALSE)), FALSE) AND COALESCE((SELECT NULLIF(rationale, '') FROM model_change_log_entries WHERE model_change_log_entry_id = p_model_change_log_entry_id) IS NULL, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_model_change_log_entries_rationale_without_question
