  SELECT ((SELECT COUNT(*) FROM knowledge_audit_items WHERE sourcing_function = (SELECT NULLIF(sourcing_function_id, '') FROM sourcing_functions WHERE sourcing_function_id = p_sourcing_function_id) AND knowledge_kind = 'Method' AND calc_knowledge_audit_items_has_internal_shortfall(knowledge_audit_item_id) = TRUE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_sourcing_functions_provider_ip_documentation_count
-- Field: SourcingFunctions.ProviderIpDocumentationCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_sourcing_functions_provider_ip_documentation_count(p_sourcing_function_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM provider_engagements WHERE sourcing_function = (SELECT NULLIF(sourcing_function_id, '') FROM sourcing_functions WHERE sourcing_function_id = p_sourcing_function_id) AND documentation_ownership = 'ProviderIP'))::integer;
$$ LANGUAGE sql STABLE;

-- calc_sourcing_functions_designs_what_it_cannot_build
-- Field: SourcingFunctions.DesignsWhatItCannotBuild
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_sourcing_functions_designs_what_it_cannot_build(p_sourcing_function_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT delivers_own_product FROM sourcing_functions WHERE sourcing_function_id = p_sourcing_function_id), FALSE), FALSE) AND COALESCE(calc_sourcing_functions_is_outsourced(p_sourcing_function_id), FALSE) AND COALESCE(COALESCE((calc_sourcing_functions_provider_ip_documentation_count(p_sourcing_function_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((calc_sourcing_functions_specification_audit_count(p_sourcing_function_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((calc_sourcing_functions_specification_shortfall_count(p_sourcing_function_id))::NUMERIC, 0) = 0, FALSE) AND COALESCE(COALESCE((calc_sourcing_functions_method_shortfall_count(p_sourcing_function_id))::NUMERIC, 0) > 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_sourcing_functions_is_unaudited_function
-- Field: SourcingFunctions.IsUnauditedFunction
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_sourcing_functions_is_unaudited_function(p_sourcing_function_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((COALESCE(calc_sourcing_functions_is_outsourced(p_sourcing_function_id), FALSE) OR COALESCE(COALESCE((SELECT is_strategically_vital FROM sourcing_functions WHERE sourcing_function_id = p_sourcing_function_id), FALSE), FALSE)), FALSE) AND COALESCE(COALESCE((calc_sourcing_functions_audit_item_count(p_sourcing_function_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_sourcing_functions_capture_initiative_count
-- Field: SourcingFunctions.CaptureInitiativeCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_sourcing_functions_capture_initiative_count(p_sourcing_function_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM knowledge_capture_initiatives WHERE sourcing_function = (SELECT NULLIF(sourcing_function_id, '') FROM sourcing_functions WHERE sourcing_function_id = p_sourcing_function_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_sourcing_functions_is_uncaptured_priority_process
-- Field: SourcingFunctions.IsUncapturedPriorityProcess
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_sourcing_functions_is_uncaptured_priority_process(p_sourcing_function_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_sourcing_functions_is_vital_expertise_process(p_sourcing_function_id), FALSE) AND COALESCE((COALESCE(calc_sourcing_functions_is_outsourced(p_sourcing_function_id), FALSE) OR COALESCE(COALESCE((calc_sourcing_functions_coverage_gap_count(p_sourcing_function_id))::NUMERIC, 0) > 0, FALSE)), FALSE) AND COALESCE(COALESCE((calc_sourcing_functions_capture_initiative_count(p_sourcing_function_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

