CREATE OR REPLACE FUNCTION calc_provider_engagements_to_client_required_count(p_provider_engagement_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM knowledge_deliverables WHERE provider_engagement = (SELECT NULLIF(provider_engagement_id, '') FROM provider_engagements WHERE provider_engagement_id = p_provider_engagement_id) AND direction = 'ToClient'))::integer;
$$ LANGUAGE sql STABLE;

-- calc_provider_engagements_to_client_delivered_count
