-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_ai_model_deployments_assignment_link_count(p_ai_model_deployment_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM role_assignments WHERE agent = calc_ai_model_deployments_agent_identifier(p_ai_model_deployment_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_ai_model_deployments_artifact_link_count
-- Field: AiModelDeployments.ArtifactLinkCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_ai_model_deployments_artifact_link_count(p_ai_model_deployment_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM execution_entities WHERE calc_execution_entities_attributed_to_agent(execution_entity_id) = calc_ai_model_deployments_agent_identifier(p_ai_model_deployment_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_ai_model_deployments_is_isolated_registry_fact
-- Field: AiModelDeployments.IsIsolatedRegistryFact
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_ai_model_deployments_is_isolated_registry_fact(p_ai_model_deployment_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_ai_model_deployments_is_live_in_production(p_ai_model_deployment_id), FALSE) AND COALESCE(COALESCE((calc_ai_model_deployments_assignment_link_count(p_ai_model_deployment_id))::NUMERIC, 0) = 0, FALSE) AND COALESCE(COALESCE((calc_ai_model_deployments_artifact_link_count(p_ai_model_deployment_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

