RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(role, '') FROM role_assignment_update_tasks WHERE role_assignment_update_task_id = p_role_assignment_update_task_id), ' ', (SELECT NULLIF(trigger_event, '') FROM role_assignment_update_tasks WHERE role_assignment_update_task_id = p_role_assignment_update_task_id), ' @ ', erb_datetime_text(((SELECT trigger_occurred_at::timestamptz FROM role_assignment_update_tasks WHERE role_assignment_update_task_id = p_role_assignment_update_task_id))::timestamptz)))::text;
