RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(outcome, '') FROM critical_incidents WHERE critical_incident_id = p_critical_incident_id), ': ', LEFT(((SELECT NULLIF(account, '') FROM critical_incidents WHERE critical_incident_id = p_critical_incident_id))::text, (60)::integer)))::text;
