-- calc_critical_incidents_is_adverse_or_improvised
-- Field: CriticalIncidents.IsAdverseOrImprovised
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_critical_incidents_is_adverse_or_improvised(p_critical_incident_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(outcome, '') FROM critical_incidents WHERE critical_incident_id = p_critical_incident_id), '') = 'WentBadly', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(outcome, '') FROM critical_incidents WHERE critical_incident_id = p_critical_incident_id), '') = 'Improvised', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_critical_incidents_has_surfaced_judgment
