$$ LANGUAGE sql STABLE;

-- calc_interview_probes_why_answer
-- Field: InterviewProbes.WhyAnswer
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_interview_probes_why_answer(p_interview_probe_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN COALESCE((SELECT NULLIF(probe_kind, '') FROM interview_probes WHERE interview_probe_id = p_interview_probe_id), '') = 'Why' THEN ((SELECT NULLIF(answer, '') FROM interview_probes WHERE interview_probe_id = p_interview_probe_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_interview_probes_shortfall_answer
