  SELECT (CASE WHEN COALESCE((SELECT NULLIF(probe_kind, '') FROM interview_probes WHERE interview_probe_id = p_interview_probe_id), '') = 'ProcedureFallsShort' THEN ((SELECT NULLIF(answer, '') FROM interview_probes WHERE interview_probe_id = p_interview_probe_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

