  SELECT (CONCAT((SELECT NULLIF(cognition_kind, '') FROM expert_cognitions WHERE expert_cognition_id = p_expert_cognition_id), ': ', LEFT(((SELECT NULLIF(statement, '') FROM expert_cognitions WHERE expert_cognition_id = p_expert_cognition_id))::text, (60)::integer)))::text;
$$ LANGUAGE sql STABLE;

-- calc_expert_cognitions_is_mental_model
-- Field: ExpertCognitions.IsMentalModel
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_expert_cognitions_is_mental_model(p_expert_cognition_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((SELECT NULLIF(cognition_kind, '') FROM expert_cognitions WHERE expert_cognition_id = p_expert_cognition_id), '') = 'MentalModel')::boolean;
$$ LANGUAGE sql STABLE;

-- calc_expert_cognitions_is_automatic_heuristic
-- Field: ExpertCognitions.IsAutomaticHeuristic
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_expert_cognitions_is_automatic_heuristic(p_expert_cognition_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(cognition_kind, '') FROM expert_cognitions WHERE expert_cognition_id = p_expert_cognition_id), '') = 'DecisionHeuristic', FALSE) AND COALESCE(COALESCE((SELECT applied_automatically FROM expert_cognitions WHERE expert_cognition_id = p_expert_cognition_id), FALSE), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_expert_cognitions_is_heuristic_oversimplified
-- Field: ExpertCognitions.IsHeuristicOversimplified
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_expert_cognitions_is_heuristic_oversimplified(p_expert_cognition_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(cognition_kind, '') FROM expert_cognitions WHERE expert_cognition_id = p_expert_cognition_id), '') = 'DecisionHeuristic', FALSE) AND COALESCE(COALESCE((SELECT expert_stated_exceptions FROM expert_cognitions WHERE expert_cognition_id = p_expert_cognition_id), FALSE), FALSE) AND COALESCE((SELECT NULLIF(captured_exceptions, '') FROM expert_cognitions WHERE expert_cognition_id = p_expert_cognition_id) IS NULL, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_concept_ladder_rungs_name
-- Field: ConceptLadderRungs.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_concept_ladder_rungs_name(p_concept_ladder_rung_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(step, '') FROM concept_ladder_rungs WHERE concept_ladder_rung_id = p_concept_ladder_rung_id), ' ', (SELECT NULLIF(rung_kind, '') FROM concept_ladder_rungs WHERE concept_ladder_rung_id = p_concept_ladder_rung_id), ': ', LEFT(((SELECT NULLIF(statement, '') FROM concept_ladder_rungs WHERE concept_ladder_rung_id = p_concept_ladder_rung_id))::text, (50)::integer)))::text;
$$ LANGUAGE sql STABLE;

-- calc_concept_ladder_rungs_step_top_level
-- Field: ConceptLadderRungs.StepTopLevel
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_concept_ladder_rungs_step_top_level(p_concept_ladder_rung_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COALESCE(MAX((ladder_level)::numeric), 0) FROM concept_ladder_rungs WHERE step = (SELECT NULLIF(step, '') FROM concept_ladder_rungs WHERE concept_ladder_rung_id = p_concept_ladder_rung_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_concept_ladder_rungs_is_ultimate_goal
-- Field: ConceptLadderRungs.IsUltimateGoal
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_concept_ladder_rungs_is_ultimate_goal(p_concept_ladder_rung_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE(((SELECT ladder_level FROM concept_ladder_rungs WHERE concept_ladder_rung_id = p_concept_ladder_rung_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((SELECT ladder_level FROM concept_ladder_rungs WHERE concept_ladder_rung_id = p_concept_ladder_rung_id), 0) = COALESCE(calc_concept_ladder_rungs_step_top_level(p_concept_ladder_rung_id), 0), FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_concept_ladder_rungs_is_decomposition_rung
-- Field: ConceptLadderRungs.IsDecompositionRung
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_concept_ladder_rungs_is_decomposition_rung(p_concept_ladder_rung_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE(((SELECT ladder_level FROM concept_ladder_rungs WHERE concept_ladder_rung_id = p_concept_ladder_rung_id))::NUMERIC, 0) < 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_repertory_grid_constructs_name
-- Field: RepertoryGridConstructs.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_repertory_grid_constructs_name(p_repertory_grid_construct_id TEXT)
RETURNS TEXT AS $$
  SELECT (calc_repertory_grid_constructs_dimension(p_repertory_grid_construct_id))::text;
$$ LANGUAGE sql STABLE;

-- calc_repertory_grid_constructs_dimension
-- Field: RepertoryGridConstructs.Dimension
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_repertory_grid_constructs_dimension(p_repertory_grid_construct_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(pole_a, '') FROM repertory_grid_constructs WHERE repertory_grid_construct_id = p_repertory_grid_construct_id), ' vs ', (SELECT NULLIF(pole_b, '') FROM repertory_grid_constructs WHERE repertory_grid_construct_id = p_repertory_grid_construct_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_repertory_grid_constructs_is_never_stated_dimension
-- Field: RepertoryGridConstructs.IsNeverStatedDimension
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_repertory_grid_constructs_is_never_stated_dimension(p_repertory_grid_construct_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(pole_a, '') FROM repertory_grid_constructs WHERE repertory_grid_construct_id = p_repertory_grid_construct_id) IS NOT NULL, FALSE) AND COALESCE(NOT (COALESCE(COALESCE((SELECT was_stated_unprompted FROM repertory_grid_constructs WHERE repertory_grid_construct_id = p_repertory_grid_construct_id), FALSE), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_repertory_grid_constructs_is_recorded_discriminating_dimen
-- Field: RepertoryGridConstructs.IsRecordedDiscriminatingDimension
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_repertory_grid_constructs_is_recorded_discriminating_dimen(p_repertory_grid_construct_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(pole_a, '') FROM repertory_grid_constructs WHERE repertory_grid_construct_id = p_repertory_grid_construct_id) IS NOT NULL, FALSE) AND COALESCE(COALESCE((SELECT separates_situations FROM repertory_grid_constructs WHERE repertory_grid_construct_id = p_repertory_grid_construct_id), FALSE), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_conversions_name
-- Field: KnowledgeConversions.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_knowledge_conversions_name(p_knowledge_conversion_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(conversion_mode, '') FROM knowledge_conversions WHERE knowledge_conversion_id = p_knowledge_conversion_id), ': ', LEFT(((SELECT NULLIF(description, '') FROM knowledge_conversions WHERE knowledge_conversion_id = p_knowledge_conversion_id))::text, (60)::integer)))::text;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_conversions_is_mode_inconsistent_with_forms
-- Field: KnowledgeConversions.IsModeInconsistentWithForms
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_conversions_is_mode_inconsistent_with_forms(p_knowledge_conversion_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (NOT (COALESCE((COALESCE((COALESCE(COALESCE((SELECT NULLIF(conversion_mode, '') FROM knowledge_conversions WHERE knowledge_conversion_id = p_knowledge_conversion_id), '') = 'Socialization', FALSE) AND COALESCE(COALESCE((SELECT NULLIF(from_form, '') FROM knowledge_conversions WHERE knowledge_conversion_id = p_knowledge_conversion_id), '') = 'Tacit', FALSE) AND COALESCE(COALESCE((SELECT NULLIF(to_form, '') FROM knowledge_conversions WHERE knowledge_conversion_id = p_knowledge_conversion_id), '') = 'Tacit', FALSE)), FALSE) OR COALESCE((COALESCE(COALESCE((SELECT NULLIF(conversion_mode, '') FROM knowledge_conversions WHERE knowledge_conversion_id = p_knowledge_conversion_id), '') = 'Externalization', FALSE) AND COALESCE(COALESCE((SELECT NULLIF(from_form, '') FROM knowledge_conversions WHERE knowledge_conversion_id = p_knowledge_conversion_id), '') = 'Tacit', FALSE) AND COALESCE(COALESCE((SELECT NULLIF(to_form, '') FROM knowledge_conversions WHERE knowledge_conversion_id = p_knowledge_conversion_id), '') = 'Explicit', FALSE)), FALSE) OR COALESCE((COALESCE(COALESCE((SELECT NULLIF(conversion_mode, '') FROM knowledge_conversions WHERE knowledge_conversion_id = p_knowledge_conversion_id), '') = 'Combination', FALSE) AND COALESCE(COALESCE((SELECT NULLIF(from_form, '') FROM knowledge_conversions WHERE knowledge_conversion_id = p_knowledge_conversion_id), '') = 'Explicit', FALSE) AND COALESCE(COALESCE((SELECT NULLIF(to_form, '') FROM knowledge_conversions WHERE knowledge_conversion_id = p_knowledge_conversion_id), '') = 'Explicit', FALSE)), FALSE) OR COALESCE((COALESCE(COALESCE((SELECT NULLIF(conversion_mode, '') FROM knowledge_conversions WHERE knowledge_conversion_id = p_knowledge_conversion_id), '') = 'Internalization', FALSE) AND COALESCE(COALESCE((SELECT NULLIF(from_form, '') FROM knowledge_conversions WHERE knowledge_conversion_id = p_knowledge_conversion_id), '') = 'Explicit', FALSE) AND COALESCE(COALESCE((SELECT NULLIF(to_form, '') FROM knowledge_conversions WHERE knowledge_conversion_id = p_knowledge_conversion_id), '') = 'Tacit', FALSE)), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_holdings_formalized_fragment_session
-- Field: KnowledgeHoldings.FormalizedFragmentSession
-- Type: lookup | DataType: string | Returns: TEXT
-- Lookup: ElicitationSession from related KnowledgeFragments


CREATE OR REPLACE FUNCTION calc_knowledge_holdings_formalized_fragment_session(p_knowledge_holding_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT elicitation_session::text FROM knowledge_fragments WHERE knowledge_fragment_id = (SELECT formalized_as FROM knowledge_holdings WHERE knowledge_holding_id = p_knowledge_holding_id));
$$ LANGUAGE sql STABLE;

-- calc_knowledge_holdings_name
-- Field: KnowledgeHoldings.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_knowledge_holdings_name(p_knowledge_holding_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(snapshot, '') FROM knowledge_holdings WHERE knowledge_holding_id = p_knowledge_holding_id), ' ', (SELECT NULLIF(carrier, '') FROM knowledge_holdings WHERE knowledge_holding_id = p_knowledge_holding_id), ': ', LEFT(((SELECT NULLIF(statement, '') FROM knowledge_holdings WHERE knowledge_holding_id = p_knowledge_holding_id))::text, (50)::integer)))::text;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_holdings_is_unformalized_process_knowledge
-- Field: KnowledgeHoldings.IsUnformalizedProcessKnowledge
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_holdings_is_unformalized_process_knowledge(p_knowledge_holding_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(formalized_as, '') FROM knowledge_holdings WHERE knowledge_holding_id = p_knowledge_holding_id) IS NULL, FALSE) AND COALESCE(COALESCE((SELECT NULLIF(carrier, '') FROM knowledge_holdings WHERE knowledge_holding_id = p_knowledge_holding_id), '') <> 'ProcedureRulebook', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_holdings_is_procedural_knowledge
-- Field: KnowledgeHoldings.IsProceduralKnowledge
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_holdings_is_procedural_knowledge(p_knowledge_holding_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((SELECT NULLIF(formalized_as, '') FROM knowledge_holdings WHERE knowledge_holding_id = p_knowledge_holding_id) IS NOT NULL)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_holdings_is_judgment_outside_document
-- Field: KnowledgeHoldings.IsJudgmentOutsideDocument
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_holdings_is_judgment_outside_document(p_knowledge_holding_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT is_unsaid_in_sop FROM knowledge_holdings WHERE knowledge_holding_id = p_knowledge_holding_id), FALSE), FALSE) AND COALESCE(calc_knowledge_holdings_is_unformalized_process_knowledge(p_knowledge_holding_id), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_holdings_is_veteran_discretion
-- Field: KnowledgeHoldings.IsVeteranDiscretion
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_holdings_is_veteran_discretion(p_knowledge_holding_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT holder_is_veteran FROM knowledge_holdings WHERE knowledge_holding_id = p_knowledge_holding_id), FALSE), FALSE) AND COALESCE(COALESCE((SELECT handles_exception_or_discretion FROM knowledge_holdings WHERE knowledge_holding_id = p_knowledge_holding_id), FALSE), FALSE) AND COALESCE(calc_knowledge_holdings_is_unformalized_process_knowledge(p_knowledge_holding_id), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_holdings_is_formalized_without_elicitation_work
-- Field: KnowledgeHoldings.IsFormalizedWithoutElicitationWork
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_holdings_is_formalized_without_elicitation_work(p_knowledge_holding_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(formalized_as, '') FROM knowledge_holdings WHERE knowledge_holding_id = p_knowledge_holding_id) IS NOT NULL, FALSE) AND COALESCE(calc_knowledge_holdings_formalized_fragment_session(p_knowledge_holding_id) IS NULL, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_fragment_corroborations_name
-- Field: FragmentCorroborations.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_fragment_corroborations_name(p_fragment_corroboration_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(knowledge_fragment, '') FROM fragment_corroborations WHERE fragment_corroboration_id = p_fragment_corroboration_id), ' via ', (SELECT NULLIF(elicitation_session, '') FROM fragment_corroborations WHERE fragment_corroboration_id = p_fragment_corroboration_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_test_outcomes_name
-- Field: KnowledgeTestOutcomes.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_knowledge_test_outcomes_name(p_knowledge_test_outcome_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(procedure, '') FROM knowledge_test_outcomes WHERE knowledge_test_outcome_id = p_knowledge_test_outcome_id), ': ', (SELECT NULLIF(outcome_area, '') FROM knowledge_test_outcomes WHERE knowledge_test_outcome_id = p_knowledge_test_outcome_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_test_outcomes_is_improved
-- Field: KnowledgeTestOutcomes.IsImproved
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_test_outcomes_is_improved(p_knowledge_test_outcome_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((COALESCE(COALESCE((SELECT higher_is_better FROM knowledge_test_outcomes WHERE knowledge_test_outcome_id = p_knowledge_test_outcome_id), FALSE), FALSE) AND COALESCE(COALESCE(((SELECT after_test_value FROM knowledge_test_outcomes WHERE knowledge_test_outcome_id = p_knowledge_test_outcome_id) > (SELECT baseline_value FROM knowledge_test_outcomes WHERE knowledge_test_outcome_id = p_knowledge_test_outcome_id)), FALSE), FALSE)), FALSE) OR COALESCE((COALESCE(NOT (COALESCE(COALESCE((SELECT higher_is_better FROM knowledge_test_outcomes WHERE knowledge_test_outcome_id = p_knowledge_test_outcome_id), FALSE), FALSE)), FALSE) AND COALESCE(COALESCE(((SELECT after_test_value FROM knowledge_test_outcomes WHERE knowledge_test_outcome_id = p_knowledge_test_outcome_id) < (SELECT baseline_value FROM knowledge_test_outcomes WHERE knowledge_test_outcome_id = p_knowledge_test_outcome_id)), FALSE), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_know_how_carriers_as_of_instant
