-- calc_know_how_carriers_source_relationship_count
-- Field: KnowHowCarriers.SourceRelationshipCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_know_how_carriers_source_relationship_count(p_know_how_carrier_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM source_relationships WHERE source_agent = (SELECT NULLIF(holder_agent, '') FROM know_how_carriers WHERE know_how_carrier_id = p_know_how_carrier_id) AND procedure = (SELECT NULLIF(procedure, '') FROM know_how_carriers WHERE know_how_carrier_id = p_know_how_carrier_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_know_how_carriers_is_held_in_both_forms
-- Field: KnowHowCarriers.IsHeldInBothForms
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_know_how_carriers_is_held_in_both_forms(p_know_how_carrier_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT is_in_written_procedure FROM know_how_carriers WHERE know_how_carrier_id = p_know_how_carrier_id), FALSE), FALSE) AND COALESCE(COALESCE((SELECT is_trained_skill FROM know_how_carriers WHERE know_how_carrier_id = p_know_how_carrier_id), FALSE), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_know_how_carriers_is_held_by_current_practitioner
-- Field: KnowHowCarriers.IsHeldByCurrentPractitioner
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_know_how_carriers_is_held_by_current_practitioner(p_know_how_carrier_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(holder_agent, '') FROM know_how_carriers WHERE know_how_carrier_id = p_know_how_carrier_id) IS NOT NULL, FALSE) AND COALESCE(COALESCE(calc_know_how_carriers_holder_is_still_engaged(p_know_how_carrier_id), FALSE) = TRUE, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_know_how_carriers_is_untransferred_veteran_know_how
-- Field: KnowHowCarriers.IsUntransferredVeteranKnowHow
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_know_how_carriers_is_untransferred_veteran_know_how(p_know_how_carrier_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_know_how_carriers_is_veteran_held(p_know_how_carrier_id), FALSE) AND COALESCE(COALESCE(calc_know_how_carriers_holder_is_still_engaged(p_know_how_carrier_id), FALSE) = TRUE, FALSE) AND COALESCE(COALESCE((calc_know_how_carriers_transfer_count(p_know_how_carrier_id))::NUMERIC, 0) = 0, FALSE) AND COALESCE(COALESCE((calc_know_how_carriers_repository_entry_count(p_know_how_carrier_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_know_how_carriers_is_at_risk_of_imminent_loss
-- Field: KnowHowCarriers.IsAtRiskOfImminentLoss
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_know_how_carriers_is_at_risk_of_imminent_loss(p_know_how_carrier_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_know_how_carriers_is_untransferred_veteran_know_how(p_know_how_carrier_id), FALSE) AND COALESCE(calc_know_how_carriers_is_holder_leaving_soon(p_know_how_carrier_id), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_know_how_carriers_is_held_only_by_departed
