CREATE OR REPLACE FUNCTION calc_know_how_carriers_transfer_stops_without_veteran(p_know_how_carrier_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_know_how_carriers_is_veteran_held(p_know_how_carrier_id), FALSE) AND COALESCE(COALESCE(calc_know_how_carriers_holder_is_still_engaged(p_know_how_carrier_id), FALSE) = TRUE, FALSE) AND COALESCE(COALESCE((calc_know_how_carriers_transfer_count(p_know_how_carrier_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((calc_know_how_carriers_repository_entry_count(p_know_how_carrier_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_know_how_carriers_builds_on_same_community_know_how
