RETURNS NUMERIC AS $$
  SELECT (CASE WHEN calc_know_how_carriers_is_held_only_by_departed(p_know_how_carrier_id) THEN (calc_know_how_carriers_holder_tenure_years(p_know_how_carrier_id))::text ELSE (0)::text END)::numeric;
$$ LANGUAGE sql STABLE;

