  SELECT ((COALESCE(calc_problem_occurrences_has_been_solved_before(p_problem_occurrence_id), FALSE) AND COALESCE(calc_problem_occurrences_prior_solution_entry(p_problem_occurrence_id) IS NULL, FALSE)))::boolean;
