-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_onboarding_records_is_recent_start(p_onboarding_record_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_onboarding_records_days_since_start(p_onboarding_record_id) AS val) SELECT ((COALESCE(COALESCE(((SELECT val FROM __erb_dedup_v1))::NUMERIC, 0) >= 0, FALSE) AND COALESCE(COALESCE(((SELECT val FROM __erb_dedup_v1))::NUMERIC, 0) <= 180, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_onboarding_records_is_starting_from_nothing
