  SELECT ((COALESCE(calc_knowledge_traces_is_document_origin(p_knowledge_trace_id), FALSE) AND COALESCE((SELECT NULLIF(step, '') FROM knowledge_traces WHERE knowledge_trace_id = p_knowledge_trace_id) IS NOT NULL, FALSE) AND COALESCE(COALESCE((calc_knowledge_traces_step_elicited_extension_count(p_knowledge_trace_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_knowledge_traces_is_document_trailing_practice
-- Field: KnowledgeTraces.IsDocumentTrailingPractice
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_traces_is_document_trailing_practice(p_knowledge_trace_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(trace_role, '') FROM knowledge_traces WHERE knowledge_trace_id = p_knowledge_trace_id), '') = 'Contradicts', FALSE) AND COALESCE((SELECT NULLIF(contradicted_document, '') FROM knowledge_traces WHERE knowledge_trace_id = p_knowledge_trace_id) IS NOT NULL, FALSE) AND COALESCE(calc_knowledge_traces_source_is_practice_evidence(p_knowledge_trace_id), FALSE) AND COALESCE(COALESCE((calc_knowledge_traces_source_collected_at(p_knowledge_trace_id) > calc_knowledge_traces_contradicted_document_revised_at(p_knowledge_trace_id)), FALSE), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_traces_prescribed_versus_enacted
-- Field: KnowledgeTraces.PrescribedVersusEnacted
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_knowledge_traces_prescribed_versus_enacted(p_knowledge_trace_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN (SELECT NULLIF(contradicted_document, '') FROM knowledge_traces WHERE knowledge_trace_id = p_knowledge_trace_id) IS NULL THEN ('')::text ELSE (CONCAT('Prescribed in ', (SELECT NULLIF(contradicted_document, '') FROM knowledge_traces WHERE knowledge_trace_id = p_knowledge_trace_id), '; enacted per ', (SELECT NULLIF(source_material, '') FROM knowledge_traces WHERE knowledge_trace_id = p_knowledge_trace_id), ': ', (SELECT NULLIF(source_statement, '') FROM knowledge_traces WHERE knowledge_trace_id = p_knowledge_trace_id)))::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_mined_flow_edges_to_step_expected_minutes
-- Field: MinedFlowEdges.ToStepExpectedMinutes
-- Type: lookup | DataType: integer | Returns: INTEGER
-- Lookup: ExpectedDurationMinutes from related Steps


CREATE OR REPLACE FUNCTION calc_mined_flow_edges_to_step_expected_minutes(p_mined_flow_edge_id TEXT)
RETURNS INTEGER AS $$
  SELECT (SELECT expected_duration_minutes::integer FROM steps WHERE step_id = (SELECT to_step FROM mined_flow_edges WHERE mined_flow_edge_id = p_mined_flow_edge_id));
$$ LANGUAGE sql STABLE;

-- calc_mined_flow_edges_name
-- Field: MinedFlowEdges.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_mined_flow_edges_name(p_mined_flow_edge_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(from_step, '') FROM mined_flow_edges WHERE mined_flow_edge_id = p_mined_flow_edge_id), ' -> ', (SELECT NULLIF(to_step, '') FROM mined_flow_edges WHERE mined_flow_edge_id = p_mined_flow_edge_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_mined_flow_edges_documented_transition_count
-- Field: MinedFlowEdges.DocumentedTransitionCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_mined_flow_edges_documented_transition_count(p_mined_flow_edge_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM step_transitions WHERE from_step = (SELECT NULLIF(from_step, '') FROM mined_flow_edges WHERE mined_flow_edge_id = p_mined_flow_edge_id) AND to_step = (SELECT NULLIF(to_step, '') FROM mined_flow_edges WHERE mined_flow_edge_id = p_mined_flow_edge_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_mined_flow_edges_is_undocumented_path
-- Field: MinedFlowEdges.IsUndocumentedPath
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_mined_flow_edges_is_undocumented_path(p_mined_flow_edge_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((calc_mined_flow_edges_documented_transition_count(p_mined_flow_edge_id))::NUMERIC, 0) = 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_mined_flow_edges_is_bottleneck
-- Field: MinedFlowEdges.IsBottleneck
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_mined_flow_edges_is_bottleneck(p_mined_flow_edge_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_mined_flow_edges_to_step_expected_minutes(p_mined_flow_edge_id) AS val) SELECT ((COALESCE(COALESCE(((SELECT val FROM __erb_dedup_v1))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((SELECT median_wait_minutes FROM mined_flow_edges WHERE mined_flow_edge_id = p_mined_flow_edge_id), 0) > COALESCE((COALESCE(4, 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v1)) AS v) __safe_numeric), 0)), 0), FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_mined_flow_edges_is_mined_path_recorded_as_intent_without_
-- Field: MinedFlowEdges.IsMinedPathRecordedAsIntentWithoutDecision
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_mined_flow_edges_is_mined_path_recorded_as_intent_without_(p_mined_flow_edge_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(recorded_stance, '') FROM mined_flow_edges WHERE mined_flow_edge_id = p_mined_flow_edge_id), '') = 'Intended', FALSE) AND COALESCE((SELECT NULLIF(intent_decision_by, '') FROM mined_flow_edges WHERE mined_flow_edge_id = p_mined_flow_edge_id) IS NULL, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_collection_occasions_as_of_instant
-- Field: CollectionOccasions.AsOfInstant
-- Type: lookup | DataType: datetime | Returns: TIMESTAMPTZ
-- Lookup: AsOfInstant from related EvaluationContexts


CREATE OR REPLACE FUNCTION calc_collection_occasions_as_of_instant(p_collection_occasion_id TEXT)
RETURNS TIMESTAMPTZ AS $$
  SELECT (SELECT as_of_instant::timestamptz FROM evaluation_contexts WHERE evaluation_context_id = (SELECT evaluation_context FROM collection_occasions WHERE collection_occasion_id = p_collection_occasion_id));
$$ LANGUAGE sql STABLE;

-- calc_collection_occasions_name
-- Field: CollectionOccasions.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_collection_occasions_name(p_collection_occasion_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(occasion_kind, '') FROM collection_occasions WHERE collection_occasion_id = p_collection_occasion_id), ': ', (SELECT NULLIF(label, '') FROM collection_occasions WHERE collection_occasion_id = p_collection_occasion_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_collection_occasions_days_since_held
-- Field: CollectionOccasions.DaysSinceHeld
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_collection_occasions_days_since_held(p_collection_occasion_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN (SELECT last_held_at::timestamptz FROM collection_occasions WHERE collection_occasion_id = p_collection_occasion_id) IS NULL THEN (0)::text ELSE ((((calc_collection_occasions_as_of_instant(p_collection_occasion_id))::timestamptz AT TIME ZONE 'UTC')::date - (((SELECT last_held_at::timestamptz FROM collection_occasions WHERE collection_occasion_id = p_collection_occasion_id))::timestamptz AT TIME ZONE 'UTC')::date))::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_collection_occasions_is_lapsed
-- Field: CollectionOccasions.IsLapsed
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_collection_occasions_is_lapsed(p_collection_occasion_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE(calc_collection_occasions_days_since_held(p_collection_occasion_id), 0) > COALESCE((SELECT cadence_days FROM collection_occasions WHERE collection_occasion_id = p_collection_occasion_id), 0))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_collection_occasions_captured_material_count
