  SELECT ((SELECT COUNT(*) FROM stakeholder_perspectives WHERE conflicts_with_perspective = (SELECT NULLIF(stakeholder_perspective_id, '') FROM stakeholder_perspectives WHERE stakeholder_perspective_id = p_stakeholder_perspective_id)))::integer;
